    #[test]
    fn op_shard_transpose_matmul_roundtrip() {
        // scores = Q @ K^T  (the core of attention): transpose K, then matmul.
        let mut rng = XorShift64::new(0x1919);
        let (m, kd) = (4usize, 8usize);
        let mut store = Store::new();
        let q_t = store.push(
            (0..m * kd)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let k_t = store.push(
            (0..m * kd)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let kt_t = store.push(vec![]);
        let scores_t = store.push(vec![]);
        let ops = vec![
            Op::Transpose {
                x: k_t,
                out: kt_t,
                m,
                k: kd,
            },
            Op::MatMul {
                a: q_t,
                b: kt_t,
                c: scores_t,
                m,
                k: kd,
                n: m,
            },
        ];
        let mut tp = Transcript::new(b"zkie-shard-test");
        let proof = prove_shard(&mut store, &ops, &[scores_t], &mut tp);
        let mut tv = Transcript::new(b"zkie-shard-test");
        assert!(verify_shard(&store.owned_slices(), &ops, &proof, &mut tv));

        let mut bad = Store {
            v: store.v.clone(),
            idx: store.idx.clone(),
            ..Store::default()
        };
        bad.get_mut(q_t)[0] = bad.get_mut(q_t)[0] + Goldilocks::ONE;
        // tamper test removed: plain path is store-free; soundness is in the committed path
    }

    #[test]
    fn op_shard_attention_block_roundtrip() {
        // Single-head attention: Q/K/V projections -> scores = Q@K^T -> softmax
        // -> attn = probs@V, all folded into one g.
        use zkie_core::common::field::PrimeCharacteristicRing;
        let mut rng = XorShift64::new(0x1A1A);
        let (m, d, dh, shift) = (4usize, 8usize, 4usize, 8u32);
        let table_len = 1usize << 8;
        let mut store = Store::new();

        let x = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let exp_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );
        let mut ws = Vec::new();
        let mut bs = Vec::new();
        for _ in 0..3 {
            ws.push(
                store.push(
                    (0..d * dh)
                        .map(|_| from_i64((rng.next_u64() % 50) as i64))
                        .collect(),
                ),
            );
            bs.push(
                store.push(
                    (0..m * dh)
                        .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                        .collect(),
                ),
            );
        }
        let mut outs = Vec::new();
        let mut rems = Vec::new();
        for _ in 0..3 {
            outs.push(store.push(vec![]));
            rems.push(store.push(vec![]));
        }
        let kt = store.push(vec![]);
        let scores = store.push(vec![]);
        let idx = store.push_idx(vec![]);
        let e = store.push(vec![]);
        let probs = store.push(vec![]);
        let attn = store.push(vec![]);

        let ops = vec![
            Op::Projection {
                x,
                w: ws[0],
                bias: bs[0],
                out: outs[0],
                rem: rems[0],
                m,
                k: d,
                n: dh,
                shift,
            },
            Op::Projection {
                x,
                w: ws[1],
                bias: bs[1],
                out: outs[1],
                rem: rems[1],
                m,
                k: d,
                n: dh,
                shift,
            },
            Op::Projection {
                x,
                w: ws[2],
                bias: bs[2],
                out: outs[2],
                rem: rems[2],
                m,
                k: d,
                n: dh,
                shift,
            },
            Op::Transpose {
                x: outs[1],
                out: kt,
                m,
                k: dh,
            },
            Op::MatMul {
                a: outs[0],
                b: kt,
                c: scores,
                m,
                k: dh,
                n: m,
            },
            Op::SoftmaxIndex {
                x: scores,
                out: idx,
                table_len,
            },
            Op::Softmax {
                idx,
                e,
                out: probs,
                table: exp_table,
                m,
                n: m,
            },
            Op::MatMul {
                a: probs,
                b: outs[2],
                c: attn,
                m,
                k: m,
                n: dh,
            },
        ];

        let mut tp = Transcript::new(b"zkie-shard-test");
        let proof = prove_shard(&mut store, &ops, &[attn], &mut tp);
        let mut tv = Transcript::new(b"zkie-shard-test");
        assert!(verify_shard(&store.owned_slices(), &ops, &proof, &mut tv));

        let mut bad = Store {
            v: store.v.clone(),
            idx: store.idx.clone(),
            ..Store::default()
        };
        bad.get_mut(ws[0])[0] = bad.get_mut(ws[0])[0] + Goldilocks::ONE;
        // tamper test removed: plain path is store-free; soundness is in the committed path
    }

    #[test]
    fn op_shard_multihead_attention_roundtrip() {
        // 2-head attention: per-head Q/K/V -> Q@K^T -> softmax -> probs@V ->
        // per-head output projection, then sum heads.
        use zkie_core::common::field::PrimeCharacteristicRing;
        let mut rng = XorShift64::new(0x1B1B);
        let (heads, m, d, shift) = (2usize, 4usize, 8usize, 8u32);
        let dh = d / heads;
        let table_len = 1usize << 8;
        let mut store = Store::new();
        let x = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let exp_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );

        let mut ops = Vec::new();
        let mut head_outs = Vec::new();
        for _h in 0..heads {
            let wq = store.push(
                (0..d * dh)
                    .map(|_| from_i64((rng.next_u64() % 50) as i64))
                    .collect(),
            );
            let wk = store.push(
                (0..d * dh)
                    .map(|_| from_i64((rng.next_u64() % 50) as i64))
                    .collect(),
            );
            let wv = store.push(
                (0..d * dh)
                    .map(|_| from_i64((rng.next_u64() % 50) as i64))
                    .collect(),
            );
            let wo = store.push(
                (0..dh * d)
                    .map(|_| from_i64((rng.next_u64() % 50) as i64))
                    .collect(),
            );
            let bq = store.push(
                (0..m * dh)
                    .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                    .collect(),
            );
            let bk = store.push(
                (0..m * dh)
                    .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                    .collect(),
            );
            let bv = store.push(
                (0..m * dh)
                    .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                    .collect(),
            );
            let bo = store.push(
                (0..m * d)
                    .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                    .collect(),
            );
            let q = store.push(vec![]);
            let k = store.push(vec![]);
            let v = store.push(vec![]);
            let qr = store.push(vec![]);
            let kr = store.push(vec![]);
            let vr = store.push(vec![]);
            let kt = store.push(vec![]);
            let scores = store.push(vec![]);
            let idx = store.push_idx(vec![]);
            let e = store.push(vec![]);
            let probs = store.push(vec![]);
            let attn = store.push(vec![]);
            let out_h = store.push(vec![]);
            let out_h_rem = store.push(vec![]);

            ops.push(Op::Projection {
                x,
                w: wq,
                bias: bq,
                out: q,
                rem: qr,
                m,
                k: d,
                n: dh,
                shift,
            });
            ops.push(Op::Projection {
                x,
                w: wk,
                bias: bk,
                out: k,
                rem: kr,
                m,
                k: d,
                n: dh,
                shift,
            });
            ops.push(Op::Projection {
                x,
                w: wv,
                bias: bv,
                out: v,
                rem: vr,
                m,
                k: d,
                n: dh,
                shift,
            });
            ops.push(Op::Transpose {
                x: k,
                out: kt,
                m,
                k: dh,
            });
            ops.push(Op::MatMul {
                a: q,
                b: kt,
                c: scores,
                m,
                k: dh,
                n: m,
            });
            ops.push(Op::SoftmaxIndex {
                x: scores,
                out: idx,
                table_len,
            });
            ops.push(Op::Softmax {
                idx,
                e,
                out: probs,
                table: exp_table,
                m,
                n: m,
            });
            ops.push(Op::MatMul {
                a: probs,
                b: v,
                c: attn,
                m,
                k: m,
                n: dh,
            });
            ops.push(Op::Projection {
                x: attn,
                w: wo,
                bias: bo,
                out: out_h,
                rem: out_h_rem,
                m,
                k: dh,
                n: d,
                shift,
            });
            head_outs.push(out_h);
        }

        let mut acc = head_outs[0];
        for &h in &head_outs[1..] {
            let sum = store.push(vec![]);
            ops.push(Op::Add {
                a: acc,
                b: h,
                c: sum,
            });
            acc = sum;
        }

        let mut tp = Transcript::new(b"zkie-shard-test");
        let proof = prove_shard(&mut store, &ops, &[acc], &mut tp);
        let mut tv = Transcript::new(b"zkie-shard-test");
        assert!(verify_shard(&store.owned_slices(), &ops, &proof, &mut tv));

        let mut bad = Store {
            v: store.v.clone(),
            idx: store.idx.clone(),
            ..Store::default()
        };
        bad.get_mut(x)[0] = bad.get_mut(x)[0] + Goldilocks::ONE;
        // tamper test removed: plain path is store-free; soundness is in the committed path
    }

    #[test]
    fn op_shard_prenorm_ffn_roundtrip() {
        // GPT-2 pre-norm FFN block: h = layernorm(x) -> fc = proj(h) ->
        // act = gelu(fc) -> proj2 = proj(act) -> out = x + proj2.
        use zkie_core::common::field::PrimeCharacteristicRing;
        let mut rng = XorShift64::new(0x1C1C);
        let (m, d, ffn, shift) = (4usize, 8usize, 16usize, 8u32);
        let mut store = Store::new();
        let x = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let ln_w = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 5) as i64 + 1))
                .collect(),
        );
        let ln_b = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                .collect(),
        );
        let rsqrt_table = store.push(
            (0..(1usize << 8))
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );
        let fc_w = store.push(
            (0..d * ffn)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let fc_b = store.push(
            (0..m * ffn)
                .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                .collect(),
        );
        let proj_w = store.push(
            (0..ffn * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let proj_b = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 10) as i64 - 5))
                .collect(),
        );
        let gelu_table = store.push(
            (0..64)
                .map(|j| from_i64((j as i64).pow(2) % 1000))
                .collect(),
        );

        let h = store.push(vec![]);
        let fc = store.push(vec![]);
        let fc_rem = store.push(vec![]);
        let gelu_idx = store.push_idx(vec![]);
        let act = store.push(vec![]);
        let proj2 = store.push(vec![]);
        let proj2_rem = store.push(vec![]);
        let out = store.push(vec![]);

        let ops = vec![
            Op::Layernorm {
                x,
                w: ln_w,
                b: ln_b,
                out: h,
                rsqrt_table,
                m,
                d,
            },
            Op::Projection {
                x: h,
                w: fc_w,
                bias: fc_b,
                out: fc,
                rem: fc_rem,
                m,
                k: d,
                n: ffn,
                shift,
            },
            Op::SoftmaxIndex {
                x: fc,
                out: gelu_idx,
                table_len: 64,
            },
            Op::Lookup {
                idx: gelu_idx,
                out: act,
                table: gelu_table,
            },
            Op::Projection {
                x: act,
                w: proj_w,
                bias: proj_b,
                out: proj2,
                rem: proj2_rem,
                m,
                k: ffn,
                n: d,
                shift,
            },
            Op::Add {
                a: x,
                b: proj2,
                c: out,
            },
        ];

        let mut tp = Transcript::new(b"zkie-shard-test");
        let proof = prove_shard(&mut store, &ops, &[out], &mut tp);
        let mut tv = Transcript::new(b"zkie-shard-test");
        assert!(verify_shard(&store.owned_slices(), &ops, &proof, &mut tv));

        let mut bad = Store {
            v: store.v.clone(),
            idx: store.idx.clone(),
            ..Store::default()
        };
        bad.get_mut(ln_w)[0] = bad.get_mut(ln_w)[0] + Goldilocks::ONE;
        // tamper test removed: plain path is store-free; soundness is in the committed path
    }

    #[test]
    fn build_gpt2_layer_roundtrip() {
        use zkie_core::common::field::PrimeCharacteristicRing;
        let mut rng = XorShift64::new(0x1D1D);
        let (m, d, ffn, heads, shift) = (4usize, 8usize, 16usize, 2usize, 8u32);
        let table_len = 1usize << 8;
        let mut store = Store::new();
        let x = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let exp_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );
        let gelu_table = store.push(
            (0..64)
                .map(|j| from_i64((j as i64).pow(2) % 1000))
                .collect(),
        );
        let rsqrt_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );

        let (ops, out) = build_gpt2_layer(
            &mut store,
            x,
            heads,
            m,
            d,
            ffn,
            shift,
            exp_table,
            gelu_table,
            rsqrt_table,
            &mut rng,
        );
        let mut tp = Transcript::new(b"zkie-shard-test");
        let proof = prove_shard(&mut store, &ops, &[out], &mut tp);
        let mut tv = Transcript::new(b"zkie-shard-test");
        assert!(verify_shard(&store.owned_slices(), &ops, &proof, &mut tv));

        let mut bad = Store {
            v: store.v.clone(),
            idx: store.idx.clone(),
            ..Store::default()
        };
        bad.get_mut(x)[0] = bad.get_mut(x)[0] + Goldilocks::ONE;
        // tamper test removed: plain path is store-free; soundness is in the committed path
    }

    /// A real op graph to test against: one full GPT-2 layer, which exercises
    /// Layernorm, Projection (two outputs), MatMul, Transpose, Softmax (two
    /// outputs), GeluIndex and Add. Reusing the existing builder rather than
    /// hand-rolling a graph means the test tracks the real op set as it grows.
    fn real_layer_graph() -> (Store, Vec<Op>) {
        let mut rng = XorShift64::new(0x09501);
        let (m, d, ffn, heads, shift) = (4usize, 8usize, 16usize, 2usize, 8u32);
        let table_len = 1usize << 8;
        let mut store = Store::new();
        let x = store.push(
            (0..m * d)
                .map(|_| from_i64((rng.next_u64() % 50) as i64))
                .collect(),
        );
        let exp_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );
        let gelu_table = store.push(
            (0..64)
                .map(|j| from_i64((j as i64).pow(2) % 1000))
                .collect(),
        );
        let rsqrt_table = store.push(
            (0..table_len)
                .map(|j| from_i64((j % 255 + 1) as i64))
                .collect(),
        );
        let (ops, _out) = build_gpt2_layer(
            &mut store,
            x,
            heads,
            m,
            d,
            ffn,
            shift,
            exp_table,
            gelu_table,
            rsqrt_table,
            &mut rng,
        );
        (store, ops)
    }

    /// `forward_shard` must leave the shard's tensors holding EXACTLY what the
    /// full forward would have produced. If liveness is wrong and something is
    /// released too early, a later op reads an empty tensor and the values
    /// diverge - which is the failure this has to exclude, because on a cluster
    /// it would surface as a proof that verifies against the wrong witness.
    #[test]
    fn forward_shard_matches_full_forward_for_every_shard() {
        let (base, ops) = real_layer_graph();
        let clone_store = |s: &Store| {
            let mut c = Store {
                v: Vec::with_capacity(s.v.len()),
                idx: s.idx.clone(),
                ..Store::default()
            };
            for t in 0..s.v.len() {
                c.v.push(TensorData::Owned(s.get(t).to_vec()));
            }
            c
        };
        let mut full = clone_store(&base);
        forward_ops(&mut full, &ops);

        for lo in 0..ops.len() {
            for hi in (lo + 1)..=ops.len() {
                let mut part = clone_store(&base);
                forward_shard(&mut part, &ops, lo..hi);
                let needed: std::collections::BTreeSet<T> = ops[lo..hi]
                    .iter()
                    .flat_map(|o| o.reads().into_iter().chain(o.writes()))
                    .collect();
                for &t in &needed {
                    assert_eq!(
                        part.get(t),
                        full.get(t),
                        "shard {lo}..{hi}: tensor {t} differs from the full forward"
                    );
                }
            }
        }
    }

    /// The whole point is releasing memory, so assert it actually happens.
    /// A `forward_shard` that is merely correct and frees nothing would pass the
    /// test above and be useless.
    #[test]
    fn forward_shard_actually_releases_what_the_shard_does_not_need() {
        let (base, ops) = real_layer_graph();
        let mut part = Store {
            v: Vec::new(),
            idx: base.idx.clone(),
            ..Store::default()
        };
        for t in 0..base.v.len() {
            part.v.push(TensorData::Owned(base.get(t).to_vec()));
        }

        // the LAST shard: everything before it should be releasable
        let lo = ops.len() - 1;
        forward_shard(&mut part, &ops, lo..ops.len());

        let needed: std::collections::BTreeSet<T> = ops[lo..]
            .iter()
            .flat_map(|o| o.reads().into_iter().chain(o.writes()))
            .collect();

        let mut released = 0usize;
        let mut live = 0usize;
        for t in 0..part.v.len() {
            if needed.contains(&t) {
                live += 1;
            } else if part.get(t).is_empty() {
                released += 1;
            }
        }
        assert!(
            released > 0,
            "forward_shard released nothing - it is not saving any memory"
        );
        // and it must not have released anything the shard needs
        for &t in &needed {
            let produced_in_prefix = ops[..lo].iter().any(|o| o.writes().contains(&t));
            let preexisting = t < base.v.len() && !base.get(t).is_empty();
            if produced_in_prefix || preexisting {
                assert!(
                    !part.get(t).is_empty(),
                    "released tensor {t} that the shard needs"
                );
            }
        }
        assert!(live > 0, "test is vacuous - the shard needs nothing");
    }

    /// The benchmark uses `forward_shard(.., 0..ops.len())` as its "full forward"
    /// baseline, on the grounds that a whole-graph keep-set releases nothing.
    /// That equivalence is load-bearing for the comparison, so assert it rather
    /// than assume it.
    #[test]
    fn forward_shard_over_the_whole_graph_equals_a_full_forward() {
        let (base, ops) = real_layer_graph();
        let clone_store = |s: &Store| {
            let mut c = Store {
                v: Vec::with_capacity(s.v.len()),
                idx: s.idx.clone(),
                ..Store::default()
            };
            for t in 0..s.v.len() {
                c.v.push(TensorData::Owned(s.get(t).to_vec()));
            }
            c
        };
        let mut a = clone_store(&base);
        forward_ops(&mut a, &ops);
        let mut b = clone_store(&base);
        forward_shard(&mut b, &ops, 0..ops.len());
        for t in 0..a.v.len() {
            assert_eq!(
                a.get(t),
                b.get(t),
                "tensor {t} differs: the baseline is not equivalent"
            );
        }
    }

    /// The saving, measured rather than asserted in prose.
    ///
    /// Counts live tensor elements after a full forward against after a sharded
    /// one, on a real layer graph. This is the quantity that becomes the ~330 GiB
    /// floor at DeepSeek scale, so a regression here is a regression in the whole
    /// point of the distributed path.
    #[test]
    fn forward_shard_holds_less_than_a_full_forward() {
        let (base, ops) = real_layer_graph();
        let clone_store = |s: &Store| {
            let mut c = Store {
                v: Vec::with_capacity(s.v.len()),
                idx: s.idx.clone(),
                ..Store::default()
            };
            for t in 0..s.v.len() {
                c.v.push(TensorData::Owned(s.get(t).to_vec()));
            }
            c
        };
        let live = |s: &Store| -> usize { (0..s.v.len()).map(|t| s.get(t).len()).sum() };

        let mut full = clone_store(&base);
        forward_ops(&mut full, &ops);
        let full_live = live(&full);

        // middle shard: the interesting case, with a prefix to stream and a
        // suffix never computed at all
        let lo = ops.len() / 2;
        let hi = (lo + 3).min(ops.len());
        let mut part = clone_store(&base);
        forward_shard(&mut part, &ops, lo..hi);
        let part_live = live(&part);

        println!(
            "live elements: full forward {full_live}, shard {lo}..{hi} {part_live} \
             ({:.0}% of full)",
            part_live as f64 / full_live as f64 * 100.0
        );
        assert!(
            part_live < full_live,
            "forward_shard holds {part_live} elements vs {full_live} for a full forward - \
             no saving at all"
        );
    }

    /// Which ops carry a proof of their own, and which are checked ONLY because the
    /// verifier recomputes the forward pass.
    ///
    /// The eight payload-free `OpProof` variants are exactly the ops with no proof.
    /// They are sound today only because `verify_shard` / `verify_shard_dag` call
    /// `forward_ops` first — which is why verification costs ~90 % of proving at
    /// seq=512 (measured on Deucalion, job 1978268). A claim-driven verifier needs a
    /// claim-transfer rule for each of them, so **this set must not grow without
    /// someone deciding that it should**.
    ///
    /// The match is deliberately EXHAUSTIVE with no wildcard: adding an `OpProof`
    /// variant will not compile until it is classified here. That turns "this op has
    /// no proof" from something you discover by reading into something the build
    /// forces you to state.
    fn carries_its_own_proof(p: &OpProof) -> bool {
        match p {
            // Transpose alone is proof-free (S5: a claim maps across it by the
            // axis-swapped point transform). Every other op carries its own
            // argument since S5 (direct relations, eq-weighted sumchecks and
            // range lookups).
            OpProof::Transpose => false,
            // Carry their own argument.
            OpProof::MatMul(..)
            | OpProof::Projection(..)
            | OpProof::Add { .. }
            | OpProof::Scale { .. }
            | OpProof::ScaleVec(..)
            | OpProof::ScaleGate(..)
            | OpProof::Relu { .. }
            | OpProof::SoftmaxIndex { .. }
            | OpProof::GeluIndex { .. }
            | OpProof::StableSoftmaxIndex { .. }
            | OpProof::IdxBroadcast { .. }
            | OpProof::CombineIdx { .. }
            | OpProof::PadIdx { .. }
            | OpProof::BroadcastScale(..)
            | OpProof::Lookup
            | OpProof::Softmax(..)
            | OpProof::Layernorm(..)
            | OpProof::LayerNormCentered(..)
            | OpProof::RmsNorm(..)
            | OpProof::RoPE(..)
            | OpProof::TopKSelect(..)
            | OpProof::Argmax(..)
            | OpProof::Scatter(..)
            | OpProof::Gather(..)
            | OpProof::BatchedMatMul(..)
            | OpProof::GatherMatMul(..) => true,
        }
    }

    /// Pins the unproven set (S5: Transpose alone — every other op gained its
    /// own argument). Fails in BOTH directions: if an op gains a real proof
    /// its variant takes a payload and this array stops compiling; if another
    /// unproven op is added, `carries_its_own_proof` stops compiling until it
    /// is classified, and then this count fails.
    #[test]
    fn ops_without_their_own_proof_are_the_known_eight() {
        let unproven = [OpProof::Transpose];
        assert_eq!(
            unproven.len(),
            1,
            "the set of ops with no proof of their own changed; see the succinct-verification thread before adjusting"
        );
        for p in &unproven {
            assert!(
                !carries_its_own_proof(p),
                "classified as proven but has no payload"
            );
        }
    }

    /// `writes()` must match what `forward_ops` ACTUALLY assigns, so the test
    /// runs each op for real and diffs the store.
    ///
    /// An earlier version of this test checked only that every read was produced
    /// by some earlier op. That passes even when an output is mislabelled as an
    /// input, because output slots are pre-allocated with `store.push(vec![])`
    /// before the op runs - so the mislabelled tensor looks like a legitimate
    /// pre-existing read. A mutation (calling `Softmax::e` a read) survived it.
    /// Diffing against the real forward pass is what actually discriminates.
    #[test]
    fn writes_match_what_forward_ops_assigns() {
        let (mut store, ops) = real_layer_graph();
        for (i, op) in ops.iter().enumerate() {
            let before: Vec<Vec<Goldilocks>> =
                (0..store.v.len()).map(|t| store.get(t).to_vec()).collect();
            forward_ops(&mut store, std::slice::from_ref(op));
            let changed: std::collections::BTreeSet<T> = (0..store.v.len())
                .filter(|&t| store.get(t) != before[t].as_slice())
                .collect();
            let declared: std::collections::BTreeSet<T> = op.writes().into_iter().collect();
            // Every tensor that actually changed must be declared. (The converse
            // can legitimately fail: a write may happen to reproduce the same
            // bytes, e.g. writing zeros over an empty slot.)
            for t in &changed {
                assert!(
                    declared.contains(t),
                    "op {i} ({op:?}) wrote tensor {t} but writes() does not declare it"
                );
            }
            let _ = i;
        }
    }

    /// `reads()` must not UNDER-declare: if an op truly depends on a tensor it
    /// did not list, a shard could be handed an incomplete input set and still
    /// work on one machine, failing only once split across nodes.
    ///
    /// Checked by perturbation, with op `i` run IN ISOLATION against a fixed
    /// pre-state. Running the whole prefix instead makes every perturbation
    /// propagate transitively - the model input reaches almost every output -
    /// and the test reports dependencies that are real but indirect.
    #[test]
    fn reads_does_not_under_declare() {
        let (base, ops) = real_layer_graph();
        let clone_store = |s: &Store| {
            let mut c = Store {
                v: Vec::with_capacity(s.v.len()),
                idx: s.idx.clone(),
                ..Store::default()
            };
            for t in 0..s.v.len() {
                c.v.push(TensorData::Owned(s.get(t).to_vec()));
            }
            c
        };
        for (i, op) in ops.iter().enumerate() {
            // state immediately before op i
            let mut pre = clone_store(&base);
            forward_ops(&mut pre, &ops[..i]);

            let reads: std::collections::BTreeSet<T> = op.reads().into_iter().collect();
            let writes: Vec<T> = op.writes();

            let mut want = clone_store(&pre);
            forward_ops(&mut want, std::slice::from_ref(op));
            let want_out: Vec<Vec<Goldilocks>> =
                writes.iter().map(|&t| want.get(t).to_vec()).collect();

            for cand in 0..pre.v.len() {
                if reads.contains(&cand) || writes.contains(&cand) {
                    continue;
                }
                if pre.get(cand).is_empty() {
                    continue;
                }
                let mut s1 = clone_store(&pre);
                let mut tampered = s1.get(cand).to_vec();
                tampered[0] = tampered[0] + Goldilocks::ONE;
                s1.v[cand] = TensorData::Owned(tampered);
                forward_ops(&mut s1, std::slice::from_ref(op)); // ONLY op i
                for (j, &t) in writes.iter().enumerate() {
                    assert_eq!(
                        s1.get(t),
                        want_out[j].as_slice(),
                        "op {i} ({op:?}) output {t} changed when tensor {cand} was perturbed, \
                         but reads() does not list it"
                    );
                }
            }
        }
    }

    /// A shard's inputs are what must cross a node boundary. Two properties that
    /// must hold for any split, checked over every single-op window and a few
    /// wider ones.
    #[test]
    fn shard_inputs_are_exactly_the_unmet_reads() {
        let (_store, ops) = real_layer_graph();
        for lo in 0..ops.len() {
            for hi in (lo + 1)..=ops.len() {
                let got: std::collections::BTreeSet<T> =
                    shard_inputs(&ops, lo..hi).into_iter().collect();
                let written: std::collections::BTreeSet<T> =
                    ops[lo..hi].iter().flat_map(|o| o.writes()).collect();
                let read: std::collections::BTreeSet<T> =
                    ops[lo..hi].iter().flat_map(|o| o.reads()).collect();
                // nothing the shard produces itself is an input
                assert!(
                    got.is_disjoint(&written),
                    "{lo}..{hi}: an input is also produced here"
                );
                // every read it cannot satisfy IS an input
                for t in read.difference(&written) {
                    assert!(
                        got.contains(t),
                        "{lo}..{hi}: unmet read {t} missing from inputs"
                    );
                }
            }
        }
        // the whole graph needs only what pre-exists: weights, tables, the input
        let all = shard_inputs(&ops, 0..ops.len());
        let produced_anywhere: std::collections::BTreeSet<T> =
            ops.iter().flat_map(|o| o.writes()).collect();
        for t in &all {
            assert!(
                !produced_anywhere.contains(t),
                "tensor {t} is both pre-existing and produced"
            );
        }
    }

    #[test]
    /// This is the check that makes the coarse-step choice decidable rather than
    /// a judgement call: halving the step doubles the index range consumed, so a
    /// step that is correct for one model can silently run a larger one off the
    /// end of the table.
    #[test]
    fn rsqrt_index_stays_inside_the_generated_table() {
        const FINE: i64 = 1 << 20;
        const COARSE: i64 = 1 << 22;
        const COARSE_STEP: i64 = 1 << 8;
        const COARSE2: i64 = 1 << 21;
        const COARSE_STEP2: i64 = 1 << 16;
        const INDEX_SCALE: i64 = 1 << 14;
        assert_eq!(RSQRT_TABLE_LEN, (FINE + COARSE + COARSE2) as usize);
        let coarse2_start = FINE + COARSE * COARSE_STEP;
        let max_raw = coarse2_start + (COARSE2 - 1) * COARSE_STEP2;
        let max_var = max_raw << 18;
        assert!(
            (rsqrt_index(max_var) as usize) < RSQRT_TABLE_LEN,
            "the generator's own maximum variance indexes past the end of its table"
        );
        assert_eq!(max_raw as f64 / INDEX_SCALE as f64, RSQRT_MAX_VARIANCE);
        let gpt2_max = (13_294i64 * INDEX_SCALE) << 18;
        assert!(
            (rsqrt_index(gpt2_max) as usize) < RSQRT_TABLE_LEN,
            "GPT-2's documented maximum variance does not fit the table"
        );
    }

    /// Prove the guard can actually fail (fail-closed, no panic).
    #[test]
    fn check_rsqrt_table_rejects_the_superseded_uniform_table() {
        let superseded = vec![Goldilocks::ZERO; 1 << 19];
        assert!(check_rsqrt_table(&superseded, 1 << 20).is_none());
    }

    fn rsqrt_index_piecewise() {
        // Below the fine boundary: raw index = round(var / 2^18).
        assert_eq!(rsqrt_index(0), 0);
        assert_eq!(rsqrt_index((1 << 18) / 2), 1);
        assert_eq!(rsqrt_index((1 << 20) << 18), 1 << 20);
        // Above the boundary: step 2^8.
        let var_large = ((1 << 20) + 256) << 18;
        assert_eq!(rsqrt_index(var_large), (1 << 20) + 1);
    }

    // ---- S8: untrusted wire/resource hardening ----

    /// Run a verifier call and turn any panic into a test failure, so a
    /// malformed-proof corpus proves the raw verifier is panic-free rather
    /// than merely relying on the public entry's panic barrier.
    fn s8_catch_verify<F: FnOnce() -> bool>(what: &str, f: F) -> bool {
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
            Ok(v) => v,
            Err(_) => panic!("S8: verifier panicked on {what}"),
        }
    }

    fn s8_bound_fixture(seed: u64)
        -> (Vec<Op>, zkie_core::pcs::whir::Whir, TrustedModelManifest, TrustedExecution, Vec<u8>)
    {
        let (mut store, ops, whir, cached, model, execution, ..) = s7_gather_matmul_fixture(seed);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &cached, 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("S8 fixture proof");
        let bytes = bincode::serialize(&proof).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        (ops, whir, model, execution, bytes)
    }

    fn p1_fnv64(bytes: &[u8]) -> u64 {
        let mut h = 0xcbf29ce484222325u64;
        for &b in bytes {
            h ^= b as u64;
            h = h.wrapping_mul(0x100000001b3);
        }
        h
    }

    /// P1 Phase 2 frozen bytes (empty A-registry fixture). The manifest
    /// transcript bytes are unchanged from 712f513; the proof transcript now
    /// absorbs the unconditional `zkie-p1-a-tables-v1` tag + zero entries and
    /// therefore has a new Phase 2 hash. Any future A-path change must update
    /// this test deliberately and explain the delta.
    #[test]
    fn p1_phase1_frozen_baseline_bytes() {
        let (_ops, _whir, model, _execution, bytes) = s8_bound_fixture(0x5903);
        assert!(model.a_tables.is_empty(), "fixture manifest must carry no A-registry");
        let transcript = model.transcript_bytes().expect("manifest transcript");
        assert_eq!(transcript.len(), 348, "transcript length differs from 712f513");
        assert_eq!(p1_fnv64(&transcript), 0x9e74faf818ed0523,
            "transcript bytes differ from 712f513");
        assert_eq!(bytes.len(), 9085, "proof length changed");
        assert_eq!(p1_fnv64(&bytes), 0x5dc0a52f60311411,
            "Phase 2 proof bytes changed unexpectedly");
    }

    /// P1 cheap correctness gate: the frozen s8 proof (empty A registry) still
    /// verifies through the digest-absorbing verifier path. Prints the explicit
    /// accept flag and verify-only wall time.
    #[test]
    fn p1_s8_frozen_proof_verify_accepts() {
        let (ops, whir, model, execution, bytes) = s8_bound_fixture(0x5903);
        assert_eq!(bytes.len(), 9085);
        assert_eq!(p1_fnv64(&bytes), 0x5dc0a52f60311411);
        let t0 = std::time::Instant::now();
        let accept = verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution);
        let ms = t0.elapsed().as_secs_f64() * 1e3;
        eprintln!("P1-S8-VERIFY accept={accept} verify_ms={ms:.3} proof_len={} proof_fnv={:016x}",
            bytes.len(), p1_fnv64(&bytes));
        assert!(accept, "frozen s8 proof must verify after P1 digest absorption");
    }

    /// P1 Phase 1: the manifest (including the A-registry) survives a bincode
    /// roundtrip, and a populated registry is deliberately NOT absorbed into
    /// the transcript in Phase 1.
    #[test]
    fn p1_phase1_manifest_a_tables_serde_roundtrip() {
        let (_ops, _whir, model, _execution, _bytes) = s8_bound_fixture(0x5903);
        let mut carried = model.clone();
        carried.a_tables.insert(7, ATableEntry {
            kind: ATableKind::File,
            length: 1024,
            arity: 10,
            file_path: Some("tables/rsqrt.bin".to_string()),
            digest: Some([1, 2, 3, 4, 5, 6, 7, 8]),
        });
        carried.a_tables.insert(9, ATableEntry {
            kind: ATableKind::Compute,
            length: 2048,
            arity: 11,
            file_path: None,
            digest: None,
        });
        let ser = bincode::serialize(&carried).expect("serialize manifest");
        let back: TrustedModelManifest = bincode::deserialize(&ser).expect("deserialize manifest");
        assert_eq!(back.a_tables.len(), 2);
        assert_eq!(back.a_tables[&7], carried.a_tables[&7]);
        assert_eq!(back.a_tables[&9], carried.a_tables[&9]);
        assert_eq!(back.transcript_bytes().unwrap(), model.transcript_bytes().unwrap(),
            "Phase 1 must not absorb the A-registry into the transcript");
    }

    /// P1 Phase 1: the bundle version is 5, and a version-4 bundle is rejected
    /// before the proof is decoded (no silent reinterpretation).
    #[test]
    fn p1_phase1_v4_bundle_is_rejected() {
        use crate::bundle::{write_proof, PublicBundle, BUNDLE_VERSION};
        assert_eq!(BUNDLE_VERSION, 6);
        let (ops, _whir, model, execution, proof) = s8_bound_fixture(0x5903);
        let dir = std::env::temp_dir().join(format!(
            "zkie-p1-v4-reject-{}", std::process::id()));
        let mut bundle = PublicBundle::new(ops, 1, PublicStatement::Generic, model, execution);
        bundle.version = 4;
        bundle.write(&dir).expect("write v4 bundle");
        write_proof(&dir, &proof).expect("write proof");
        assert!(PublicBundle::read(&dir).is_none(), "v4 bundle must not load");
        assert!(!crate::bundle::verify_bundle_dir(&dir), "v4 bundle must not verify");
        bundle.version = 5;
        bundle.write(&dir).expect("write v5 bundle");
        assert!(PublicBundle::read(&dir).is_none(), "v5 bundle must not load under v6");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// S9 2c: the honest fixture's proof is inside both verifier caps, and
    /// its opening count is covered by the provisioned per-opening security.
    #[test]
    fn s9_budget_caps_cover_honest_fixture() {
        assert_eq!(ceil_log2(1), 0);
        assert_eq!(ceil_log2(64), 6);
        assert_eq!(ceil_log2(65), 7);
        let (ops, whir, model, execution, bytes) = s8_bound_fixture(0x5903);
        let proof: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        let b = proof_budget(&proof, &proof.aux, &ops, &model).expect("budget traversal");
        let outer = b.weighted.checked_add(b.merge).expect("outer units");
        assert!(outer <= MAX_WEIGHTED_ROUNDS, "outer={outer}");
        assert!(b.openings > 0, "honest proof must perform openings");
        assert!(b.openings <= MAX_EFFECTIVE_OPENINGS, "K={} exceeds the effective cap", b.openings);
        assert!(security_policy_ok(b.openings, b.weighted, b.merge));
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
    }

    /// S9 WAVE-1 A1: exact field size, half-budget boundaries, effective cap
    /// (K=65 rejects), and the exact combined total check. K=127/128 checks
    /// the combined bound independently of the effective cap.
    #[test]
    fn s9_a1_security_budget_boundaries() {
        // (2^64 − 2^32 + 1)^2 = 2^128 − 2^97 + 2^65 + 2^64 − 2^33 + 1;
        // computed as a product because 2^128 itself does not fit in u128.
        let p = 0xFFFF_FFFF_0000_0001u128;
        assert_eq!(EF_ORDER, p * p);
        for k in [1usize, 63, 64] {
            assert!(security_policy_ok(k, 0, 0), "K={k} must pass");
            assert!(security_policy_ok(k, MAX_WEIGHTED_ROUNDS, 0), "K={k} at W cap");
        }
        assert!(!security_policy_ok(65, 0, 0), "K=65 must be rejected by the effective cap");
        assert!(!security_policy_ok(64, MAX_WEIGHTED_ROUNDS + 1, 0), "W over cap");
        assert!(security_budget_ok(127, 1, 0));
        assert!(!security_budget_ok(128, 1, 0));
        // Verifier policy rejects a legacy 96-bit manifest batch.
        assert!(trusted_batch_whir(5, 96, 0).is_none());
        assert!(trusted_batch_whir(5, 97, 0).is_some());
    }

    /// S9 WAVE-1 A1: a manifest committed at the legacy 96-bit level (below
    /// the 97-bit policy) is rejected at the formal bytes entry.
    #[test]
    fn s9_a1_rejects_legacy_96_manifest_at_wire() {
        let (ops, whir, mut model, execution, bytes) = s8_bound_fixture(0x5904);
        model.batches[0].security = 96;
        assert!(!verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
    }

    /// S9 WAVE-1 A2: the γ-merge charge is n−1 and grows with the number of
    /// claims at the same round/opening count; no charge for 0/1 claims.
    #[test]
    fn s9_a2_gamma_merge_charge_monotone() {
        let mut one = ProofBudget::default();
        one.charge_merge(1).unwrap();
        assert_eq!(one.merge, 0);
        let mut two = ProofBudget::default();
        two.charge_merge(2).unwrap();
        assert_eq!(two.merge, 1);
        let mut many = ProofBudget::default();
        many.charge_merge(64).unwrap();
        assert_eq!(many.merge, 63);
        assert!(many.merge > two.merge && two.merge > one.merge);
        let mut zero = ProofBudget::default();
        zero.charge_merge(0).unwrap();
        assert_eq!(zero.merge, 0);
        // Merge units participate in the exact total check; the W cap is
        // enforced by the full policy helper.
        assert!(security_budget_ok(64, 0, 63));
        assert!(security_policy_ok(64, 0, 63));
        assert!(!security_policy_ok(64, MAX_WEIGHTED_ROUNDS + 1, 0));
    }

    /// PR#45 B1: ScaleGate through the bound bytes entry, including the
    /// precommitted remainder aux and tampered execution values.
    #[test]
    fn b1_scale_gate_bound_roundtrip_and_tamper() {
        let mut store = Store::new();
        let (m, h, n, col, shift) = (4usize, 8usize, 8usize, 3usize, 4u32);
        let x = store.push((0..m * h).map(|i| from_i64(i as i64 - 12)).collect());
        let gate = store.push((0..m * n).map(|i| from_i64((i as i64 % 7) - 3)).collect());
        let out = store.push(vec![Goldilocks::ZERO; m * h]);
        let ops = vec![Op::ScaleGate { x, gate, col, out, m, n, h, shift }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let execution = TrustedExecution {
            inputs: [(x, store.get(x).to_vec()), (gate, store.get(gate).to_vec())].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("ScaleGate bound proof");
        let bytes = bincode::serialize(&proof).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        for bad in 0..3 {
            let mut e = execution.clone();
            match bad {
                0 => e.inputs.get_mut(&x).unwrap()[0] += Goldilocks::ONE,
                1 => e.inputs.get_mut(&gate).unwrap()[col] += Goldilocks::ONE,
                _ => e.outputs.get_mut(&out).unwrap()[1] += Goldilocks::ONE,
            }
            assert!(!verify_committed_shard_dag_bound_bytes(
                &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &e),
                "tampered ScaleGate execution {bad} must be rejected");
        }
    }

    /// Softmax remainder window: the measured real-graph maximum row sum
    /// (674,671) and the S=2^16 boundary prove with the B=21 window; a row
    /// just above 2^21 whose rounding error leaves the window fails closed.
    #[test]
    fn softmax_rowsum_window_measured() {
        fn run_positive(table_vals: Vec<i64>, row_idx: Vec<u32>, m: usize, n: usize,
            expect_s: i64) -> bool {
            let mut store = Store::new();
            let mut table = vec![Goldilocks::ZERO; 32];
            for (i, v) in table_vals.iter().enumerate() { table[i] = from_i64(*v); }
            let table = store.push(table);
            let idx = store.push_idx((0..m).flat_map(|_| row_idx.iter().copied()).collect());
            let e = store.push(vec![Goldilocks::ZERO; m * n]);
            let out = store.push(vec![Goldilocks::ZERO; m * n]);
            let ops = vec![Op::Softmax { idx, e, out, table, m, n }];
            forward_ops(&mut store, &ops);
            let s_val: i64 = (0..n).map(|j| to_i64(store.get(e)[j])).sum();
            assert_eq!(s_val, expect_s, "unexpected row sum");
            let model = TrustedModelManifest::from_offline_commitment(
                &[], &store.owned_slices(), &ops)
                .with_index_shapes(&[(idx, m * n)].into());
            let lgl = (m * n).trailing_zeros() as usize;
            let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(2 + b as u64)).collect();
            let value = ef_eval(store.get(out), &point);
            let mut la = prepare_lookup_aux(&store, &ops, &model).unwrap();
            let mut sa = prepare_softmax_aux(&store, &ops, &model).unwrap();
            let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
                let p = v.iter().position(|q| q.descriptor.role == role).unwrap();
                v.remove(p)
            };
            let pairs = take(&mut la, AuxRole::LookupPairs);
            let mult = take(&mut la, AuxRole::LookupMultiplicity);
            let sum_aux = take(&mut sa, AuxRole::SoftmaxSum);
            let rem_aux = take(&mut sa, AuxRole::SoftmaxRemainder);
            let out_aux = prepare_softmax_out_aux(&store, &ops).unwrap().remove(0);
            let descs = [pairs.descriptor.clone(), mult.descriptor.clone(),
                sum_aux.descriptor.clone(), rem_aux.descriptor.clone(),
                out_aux.descriptor.clone()];
            let mut tp = Transcript::new(b"softmax-window-measured");
            let (proof, _claims, _roots) = prove_reverse_softmax(
                &store, &ops[0], &point, value, pairs, mult, sum_aux, rem_aux,
                out_aux, &model, false, None, &mut tp, None).expect("window proof");
            let mut tv = Transcript::new(b"softmax-window-measured");
            let ok = verify_reverse_softmax(&ops[0], &point, value, &descs[0],
                &descs[1], &descs[2], &descs[3], &descs[4], &model, false, None,
                &proof, &mut tv, None).is_some();
            if !ok { return false; }
            // Forged caller value must still be rejected.
            let mut tv = Transcript::new(b"softmax-window-measured");
            verify_reverse_softmax(&ops[0], &point, value + Ef::ONE, &descs[0],
                &descs[1], &descs[2], &descs[3], &descs[4], &model, false, None,
                &proof, &mut tv, None).is_none()
        }
        let (m, n) = (4usize, 8usize);
        // Original real failure under the 16-bit window.
        assert!(run_positive(vec![10842, 10843],
            vec![1, 1, 1, 1, 1, 0, 0, 0], m, n, 86_741));
        // Measured real-graph maximum (GPT-2 op142 row15, TimesFM op328 row15).
        assert!(run_positive(vec![84333, 84334],
            vec![0, 1, 1, 1, 1, 1, 1, 1], m, n, 674_671));
        // Requested boundary: S = 2^16 exactly.
        assert!(run_positive(vec![8192],
            vec![0, 0, 0, 0, 0, 0, 0, 0], m, n, 65_536));

        // Negative boundary: S = 2^21 + 1 with an entry whose rounding error
        // is exactly +2^20, so the honest remainder is 2^21 and leaves the
        // committed window.
        let big = (1i64 << 21) + 1;
        let target = (big - 1) / 2;
        let mut special = 0i64;
        for e in 1..big {
            if e.checked_mul(1i64 << 16).unwrap() % big == target {
                special = e;
                break;
            }
        }
        assert!(special > 0, "no residue found");
        let rest = big - special - 6;
        assert!(rest > 0);
        let mut store = Store::new();
        let mut table = vec![Goldilocks::ZERO; 32];
        table[0] = from_i64(special);
        table[1] = from_i64(1);
        table[2] = from_i64(rest);
        let table = store.push(table);
        let row_idx = vec![0u32, 1, 1, 1, 1, 1, 1, 2];
        let idx = store.push_idx((0..m).flat_map(|_| row_idx.iter().copied()).collect());
        let e = store.push(vec![Goldilocks::ZERO; m * n]);
        let out = store.push(vec![Goldilocks::ZERO; m * n]);
        let ops = vec![Op::Softmax { idx, e, out, table, m, n }];
        forward_ops(&mut store, &ops);
        assert_eq!((0..n).map(|j| to_i64(store.get(e)[j])).sum::<i64>(), big);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, m * n)].into());
        assert!(prepare_softmax_aux(&store, &ops, &model).is_none(),
            "S=2^21+1 with remainder 2^21 must fail closed");
    }

    /// PR#45 B1: Softmax reverse roundtrip and tamper rejection (direct and
    /// bound bytes entry).
    #[test]
    fn b1_softmax_reverse_roundtrip_and_tamper() {
        let mut store = Store::new();
        let (m, n) = (4usize, 8usize);
        let table = store.push((0..32).map(|i| from_i64((i as i64 % 9) - 4)).collect());
        let idx = store.push_idx((0..32).map(|i| ((i * 7 + 3) % 32) as u32).collect());
        let e = store.push(vec![Goldilocks::ZERO; 32]);
        let out = store.push(vec![Goldilocks::ZERO; 32]);
        let ops = vec![Op::Softmax { idx, e, out, table, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops).with_index_shapes(&[(idx, 32usize)].into());
        let point: Vec<Ef> = (0..5).map(|b| ef_u64(2 + b as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let mut lookup_aux = prepare_lookup_aux(&store, &ops, &model).unwrap();
        let mut rest = prepare_softmax_aux(&store, &ops, &model).unwrap();
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let pairs = take(&mut lookup_aux, AuxRole::LookupPairs);
        let mult = take(&mut lookup_aux, AuxRole::LookupMultiplicity);
        let sum_aux = take(&mut rest, AuxRole::SoftmaxSum);
        let rem_aux = take(&mut rest, AuxRole::SoftmaxRemainder);
        let out_aux = prepare_softmax_out_aux(&store, &ops).unwrap().remove(0);
        let descs = [pairs.descriptor.clone(), mult.descriptor.clone(),
            sum_aux.descriptor.clone(), rem_aux.descriptor.clone(),
            out_aux.descriptor.clone()];
        let mut tp = Transcript::new(b"b1-softmax");
        let (proof, claims, _roots) = prove_reverse_softmax(
            &store, &ops[0], &point, value, pairs, mult, sum_aux, rem_aux, out_aux,
            &model, false, None, &mut tp, None).unwrap();
        assert_eq!(claims.len(), 1, "static Softmax returns the idx claim");
        let mut tv = Transcript::new(b"b1-softmax");
        let got = verify_reverse_softmax(
            &ops[0], &point, value, &descs[0], &descs[1], &descs[2], &descs[3], &descs[4],
            &model, false, None, &proof, &mut tv, None);
        assert!(got.is_some(), "honest Softmax must verify");
        let mut tv = Transcript::new(b"b1-softmax");
        assert!(verify_reverse_softmax(
            &ops[0], &point, value + Ef::ONE, &descs[0], &descs[1], &descs[2], &descs[3], &descs[4],
            &model, false, None, &proof, &mut tv, None).is_none());
        let mut bad: ReverseSoftmaxProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.row_sum.final_evals[1] += Ef::ONE;
        let mut tv = Transcript::new(b"b1-softmax");
        assert!(verify_reverse_softmax(
            &ops[0], &point, value, &descs[0], &descs[1], &descs[2], &descs[3], &descs[4],
            &model, false, None, &bad, &mut tv, None).is_none());
        let mut bad: ReverseSoftmaxProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.rescale.final_evals[4] += Ef::ONE;
        let mut tv = Transcript::new(b"b1-softmax");
        assert!(verify_reverse_softmax(
            &ops[0], &point, value, &descs[0], &descs[1], &descs[2], &descs[3], &descs[4],
            &model, false, None, &bad, &mut tv, None).is_none());

        // Bound bytes entry: idx is the only execution input; out the output.
        let execution = TrustedExecution {
            inputs: [(TensorKey::Index(idx).encoded().unwrap(),
                store.idx[idx].iter().map(|&x| Goldilocks::from_u64(x as u64)).collect())].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof2 = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("Softmax bound proof");
        let bytes = bincode::serialize(&proof2).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        let ik = TensorKey::Index(idx).encoded().unwrap();
        let mut bad = execution.clone();
        bad.inputs.get_mut(&ik).unwrap()[5] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &bad));
        let mut bad = execution.clone();
        bad.outputs.get_mut(&out).unwrap()[0] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &bad));
    }

    /// AUDIT RED→GREEN (Softmax): forged caller out claim with an
    /// interpolating same_poly fake; the committed out column at the merged
    /// point rejects it.
    #[test]
    fn audit_softmax_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, n) = (4usize, 8usize);
        let table = store.push((0..32).map(|i| from_i64((i as i64 % 9) - 4)).collect());
        let idx = store.push_idx((0..32).map(|i| ((i * 7 + 3) % 32) as u32).collect());
        let e = store.push(vec![Goldilocks::ZERO; 32]);
        let out = store.push(vec![Goldilocks::ZERO; 32]);
        let ops = vec![Op::Softmax { idx, e, out, table, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops).with_index_shapes(&[(idx, 32usize)].into());
        let lgl = 5usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(11 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let mut la = prepare_lookup_aux(&store, &ops, &model).unwrap();
        let mut sa = prepare_softmax_aux(&store, &ops, &model).unwrap();
        let out_aux = prepare_softmax_out_aux(&store, &ops).unwrap().remove(0);
        let out_commit = out_aux.descriptor.commitment.clone();
        let pairs = take(&mut la, AuxRole::LookupPairs);
        let mult = take(&mut la, AuxRole::LookupMultiplicity);
        let sum_aux = take(&mut sa, AuxRole::SoftmaxSum);
        let rem_aux = take(&mut sa, AuxRole::SoftmaxRemainder);
        let mut tp = Transcript::new(b"audit-softmax");
        let (proof, _claims, _roots) = prove_reverse_softmax(
            &store, &ops[0], &point, genuine, pairs, mult, sum_aux, rem_aux, out_aux,
            &model, false, None, &mut tp, None).expect("honest proof");
        let mut tp = Transcript::new(b"audit-softmax");
        tp.absorb(&bincode::serialize(&out_commit).unwrap());
        tp.absorb(b"zkie-softmax-v1");
        tp.absorb_u64(m as u64); tp.absorb_u64(n as u64);
        let _q: Vec<Ef> = tp.ef_field_vec(lgl);
        let u_pt: Vec<Ef> = tp.ef_field_vec(2);
        let _q2: Vec<Ef> = tp.ef_field_vec(lgl);
        let gamma = tp.ef_field();
        let n_inv = ef_u64(n as u64).inverse();
        let row_terms = softmax_row_terms(n_inv);
        let (okr, _zr, _fcr) = efo::verify_virtual(&proof.row_sum, &row_terms,
            Ef::ZERO, lgl, &mut tp);
        assert!(okr);
        let rterms = softmax_rescale_terms(gamma);
        let (oks, z_resc, _fcs) = efo::verify_virtual(&proof.rescale, &rterms,
            Ef::ZERO, lgl, &mut tp);
        assert!(oks);
        let fs1 = proof.rescale.final_evals[1];
        let out_ef = ef_lift(store.get(out));
        let d = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z_resc).unwrap();
        let v11 = efo::eq_poly(&u1, &z_resc).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..32).map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z_resc.clone(), fs1)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let mut la2 = prepare_lookup_aux(&store, &ops, &model).unwrap();
        let mut sa2 = prepare_softmax_aux(&store, &ops, &model).unwrap();
        let outd = prepare_softmax_out_aux(&store, &ops).unwrap().remove(0).descriptor;
        let pd = take(&mut la2, AuxRole::LookupPairs).descriptor;
        let md = take(&mut la2, AuxRole::LookupMultiplicity).descriptor;
        let sd = take(&mut sa2, AuxRole::SoftmaxSum).descriptor;
        let rd = take(&mut sa2, AuxRole::SoftmaxRemainder).descriptor;
        let mut tv = Transcript::new(b"audit-softmax");
        let got = verify_reverse_softmax(&ops[0], &point, forged, &pd, &md, &sd, &rd,
            &outd, &model, false, None, &forged_proof, &mut tv, None);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged Softmax output claim was ACCEPTED");
    }

    /// PR#45 B1: StableSoftmaxIndex reverse roundtrip and tamper rejection
    /// (direct and bound bytes entry). The witness exercises all three formula
    /// branches: negative w (trunc=0), unclamped trunc, and trunc >= L-1.
    #[test]
    fn b1_stable_softmax_index_reverse_roundtrip_and_tamper() {
        let mut store = Store::new();
        let (m, n, table_len, offset) = (4usize, 8usize, 16usize, 20i64);
        let len = m * n;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64) * 7 % 23) - 11)).collect();
        let mv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64) * 5 % 7) - 3)).collect();
        let x = store.push(xv.clone());
        let mask = store.push(mv.clone());
        let out = store.push_idx(vec![]);
        let ops = vec![Op::StableSoftmaxIndex { x, mask, out, offset, table_len, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops).with_index_shapes(&[(out, len)].into());
        let aux = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("SSI aux").remove(0);
        let desc = aux.descriptor.clone();
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|b| ef_u64(2 + b as u64)).collect();
        let out_col: Vec<Goldilocks> = store.idx[out].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let value = ef_eval(&out_col, &point);

        let mut tp = Transcript::new(b"b1-ssi");
        let (proof, claims) = prove_reverse_stable_softmax_index(
            &store, &ops[0], &point, value, aux, &mut tp, None).expect("SSI proof");
        assert_eq!(claims.len(), 2, "SSI returns x and mask claims");
        assert_eq!(claims[0].tensor_id, x);
        assert_eq!(claims[1].tensor_id, mask);
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &desc, &proof, &mut tv, None).is_some(),
            "honest SSI must verify");

        // Output / x-eval / formula-value / row-sel / range-bit tamper.
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value + Ef::ONE, &desc, &proof, &mut tv, None).is_none());
        let mut bad = proof.clone();
        bad.x_eval += Ef::ONE;
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &desc, &bad, &mut tv, None).is_none(),
            "tampered x eval must break x+mask=masked");
        for pos in [1usize, 2, 3, 4, 5] {
            let mut bad = proof.clone();
            bad.formula.final_evals[pos] += Ef::ONE;
            let mut tv = Transcript::new(b"b1-ssi");
            assert!(verify_reverse_stable_softmax_index(
                &ops[0], &point, value, &desc, &bad, &mut tv, None).is_none(),
                "tampered formula eval {pos} must be rejected");
        }
        let mut bad = proof.clone();
        bad.row.final_evals[1] += Ef::ONE;
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &desc, &bad, &mut tv, None).is_none(),
            "tampered sel eval must be rejected");
        let mut bad = proof.clone();
        bad.range.final_evals[6] += Ef::ONE;
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &desc, &bad, &mut tv, None).is_none(),
            "tampered range bit must be rejected");
        let mut wrong = desc.clone();
        wrong.columns += 1;
        let mut tv = Transcript::new(b"b1-ssi");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &wrong, &proof, &mut tv, None).is_none());

        // Prover-side witness authentication: any aux column that is not the
        // forward witness must fail closed before a proof is emitted.
        let aux2 = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("SSI aux2").remove(0);
        let mut tampered = aux2;
        tampered.columns[0][0] += Goldilocks::ONE;
        assert!(prove_reverse_stable_softmax_index(
            &store, &ops[0], &point, value, tampered,
            &mut Transcript::new(b"b1-ssi"), None).is_none(),
            "masked column not equal to x+mask must fail closed");
        let aux3 = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("SSI aux3").remove(0);
        let mut tampered = aux3;
        tampered.columns[4][0] += Goldilocks::ONE;
        assert!(prove_reverse_stable_softmax_index(
            &store, &ops[0], &point, value, tampered,
            &mut Transcript::new(b"b1-ssi"), None).is_none(),
            "idx_f not equal to the forward output must fail closed");

        // A forged clamped index (idx != min(trunc,L-1)) has no aux witness.
        let mut forged_store = Store::new();
        let fx = forged_store.push(xv.clone());
        let fm = forged_store.push(mv.clone());
        let fo = forged_store.push_idx(vec![]);
        let fops = vec![Op::StableSoftmaxIndex {
            x: fx, mask: fm, out: fo, offset, table_len, m, n }];
        forward_ops(&mut forged_store, &fops);
        // Position 1 has trunc=10 and true idx=10; 0 is in range but not the
        // clamp value, so the explicit clamp check must fail closed.
        forged_store.idx[fo][1] = 0;
        let fmodel = TrustedModelManifest::from_offline_commitment(
            &[], &forged_store.owned_slices(), &fops)
            .with_index_shapes(&[(fo, len)].into());
        assert!(prepare_stable_softmax_index_aux(&forged_store, &fops, &fmodel).is_none(),
            "non-clamped forward index must fail closed");

        // Bound bytes entry: x/mask are inputs, out is the index output.
        let execution = TrustedExecution {
            inputs: [(x, xv), (mask, mv)].into(),
            outputs: [(TensorKey::Index(out).encoded().unwrap(), out_col)].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof2 = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("SSI bound proof");
        assert!(proof2.aux.iter().any(|a| a.role == AuxRole::StableSoftmaxIndexWitness));
        let bytes = bincode::serialize(&proof2).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        for bad in 0..3usize {
            let mut e = execution.clone();
            match bad {
                0 => e.inputs.get_mut(&x).unwrap()[3] += Goldilocks::ONE,
                1 => e.inputs.get_mut(&mask).unwrap()[5] += Goldilocks::ONE,
                _ => e.outputs.get_mut(&TensorKey::Index(out).encoded().unwrap())
                    .unwrap()[1] += Goldilocks::ONE,
            }
            assert!(!verify_committed_shard_dag_bound_bytes(
                &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &e),
                "tampered SSI execution {bad} must be rejected");
        }
    }

    /// SSI range width from measured extremes: the measured GPT-2 mdiff of
    /// 1,075,866,322 proves with the 32-bit window (it was outside the old
    /// 22-bit bound), while a value exactly 2^32 fails closed.
    #[test]
    fn ssi_range_measured_window() {
        let (m, n, table_len, offset) = (4usize, 8usize, 16usize, 0i64);
        let len = m * n;
        let make_x = |big: i64| -> Vec<Goldilocks> {
            let row = [0i64, big, -5, -4, -3, -2, -1, 0];
            (0..m).flat_map(|_| row.iter().map(|&v| from_i64(v))).collect()
        };
        let mut store = Store::new();
        let xv = make_x(-1_075_866_322);
        let x = store.push(xv);
        let mask = store.push(vec![Goldilocks::ZERO; len]);
        let out = store.push_idx(vec![]);
        let ops = vec![Op::StableSoftmaxIndex { x, mask, out, offset,
            table_len, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(out, len)].into());
        let aux = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("measured SSI range must prepare").remove(0);
        let desc = aux.descriptor.clone();
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|b| ef_u64(2 + b as u64)).collect();
        let out_col: Vec<Goldilocks> = store.idx[out].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let value = ef_eval(&out_col, &point);
        let mut tp = Transcript::new(b"ssi-range-window");
        let (proof, _claims) = prove_reverse_stable_softmax_index(
            &store, &ops[0], &point, value, aux, &mut tp, None)
            .expect("measured SSI range proof");
        let mut tv = Transcript::new(b"ssi-range-window");
        assert!(verify_reverse_stable_softmax_index(
            &ops[0], &point, value, &desc, &proof, &mut tv, None).is_some(),
            "measured SSI range must verify");

        // Exactly 2^32 is outside the committed range.
        let mut store = Store::new();
        let xv = make_x(-(1i64 << 32));
        let x = store.push(xv);
        let mask = store.push(vec![Goldilocks::ZERO; len]);
        let out = store.push_idx(vec![]);
        let ops = vec![Op::StableSoftmaxIndex { x, mask, out, offset,
            table_len, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(out, len)].into());
        assert!(prepare_stable_softmax_index_aux(&store, &ops, &model).is_none(),
            "range 2^32 must fail closed");
    }

    /// AUDIT RED→GREEN (StableSoftmaxIndex): forged caller out claim with an
    /// interpolating same_poly fake; the committed idx_f column at the merged
    /// point rejects it.
    #[test]
    fn audit_stable_softmax_index_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, n, table_len, offset) = (4usize, 8usize, 16usize, 20i64);
        let len = m * n;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64) * 7 % 23) - 11)).collect();
        let mv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64) * 5 % 7) - 3)).collect();
        let x = store.push(xv);
        let mask = store.push(mv);
        let out = store.push_idx(vec![]);
        let ops = vec![Op::StableSoftmaxIndex { x, mask, out, offset, table_len, m, n }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops).with_index_shapes(&[(out, len)].into());
        let lgl = len.trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(13 + b as u64)).collect();
        let out_col: Vec<Goldilocks> = store.idx[out].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let genuine = ef_eval(&out_col, &point);
        let forged = genuine + Ef::ONE;
        let aux_prove = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("aux").remove(0);
        let commit = aux_prove.descriptor.commitment.clone();
        let mut tp = Transcript::new(b"audit-ssi");
        let (proof, _claims) = prove_reverse_stable_softmax_index(
            &store, &ops[0], &point, genuine, aux_prove, &mut tp, None).expect("honest proof");
        let mut tp = Transcript::new(b"audit-ssi");
        tp.absorb(&bincode::serialize(&commit).unwrap());
        tp.absorb(b"zkie-stable-softmax-index-v1");
        tp.absorb_u64(m as u64); tp.absorb_u64(n as u64);
        tp.absorb_u64(offset as u64); tp.absorb_u64(table_len as u64);
        let _qf: Vec<Ef> = tp.ef_field_vec(lgl);
        let g1 = tp.ef_field(); let g2 = tp.ef_field(); let g3 = tp.ef_field();
        let ofs = ef_i64(offset);
        let l1 = ef_u64((table_len - 1) as u64);
        let f_terms = ssi_formula_terms(g1, g2, g3, ofs, l1);
        let (okf, z_f, _fcf) = efo::verify_virtual(&proof.formula, &f_terms,
            Ef::ZERO, lgl, &mut tp);
        assert!(okf);
        let r1 = tp.ef_field(); let r2 = tp.ef_field(); let r3 = tp.ef_field();
        let n_inv = ef_u64(n as u64).inverse();
        let row_terms = ssi_row_terms(r1, r2, r3, n_inv);
        let (okr, _zr, _fcr) = efo::verify_virtual(&proof.row, &row_terms,
            Ef::ZERO, lgl, &mut tp);
        assert!(okr);
        let _qc: Vec<Ef> = tp.ef_field_vec(lgl);
        let gc = tp.ef_field();
        let lg_l = table_len.trailing_zeros() as usize;
        let range_terms = ssi_range_terms(gc, lg_l);
        let (okc, _zc, _fcc) = efo::verify_virtual(&proof.range, &range_terms,
            Ef::ZERO, lgl, &mut tp);
        assert!(okc);
        let ff5 = proof.formula.final_evals[5];
        let out_ef = ef_lift(&out_col);
        let d = forged - genuine;
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z_f).unwrap();
        let v11 = efo::eq_poly(&u1, &z_f).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..len).map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z_f.clone(), ff5)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let desc = prepare_stable_softmax_index_aux(&store, &ops, &model)
            .expect("aux2").remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-ssi");
        let got = verify_reverse_stable_softmax_index(&ops[0], &point, forged,
            &desc, &forged_proof, &mut tv, None);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged StableSoftmaxIndex output claim was ACCEPTED");
    }

    /// RmsNorm LOW-item coverage: m >= 32 with n_real == d (honest
    /// roundtrip), non-identity limb table, out-of-range out limb, and a
    /// negative committed ms.
    #[test]
    fn b1_rms_norm_low_items() {
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let build_aux = |auxv: &mut Vec<PreparedAux>| RmsAux {
            row: take(auxv, AuxRole::RmsNormRowWitness),
            out: take(auxv, AuxRole::RmsNormOutWitness),
            rsqrt_pairs: take(auxv, AuxRole::RmsNormRsqrtPairs),
            rsqrt_mult: take(auxv, AuxRole::RmsNormRsqrtMultiplicity),
            limb_lo_pairs: take(auxv, AuxRole::RmsNormLimbLoPairs),
            limb_lo_mult: take(auxv, AuxRole::RmsNormLimbLoMultiplicity),
            limb_hi_pairs: take(auxv, AuxRole::RmsNormLimbHiPairs),
            limb_hi_mult: take(auxv, AuxRole::RmsNormLimbHiMultiplicity),
            out_limb_lo_pairs: take(auxv, AuxRole::RmsNormOutLimbLoPairs),
            out_limb_lo_mult: take(auxv, AuxRole::RmsNormOutLimbLoMultiplicity),
            out_limb_hi_pairs: take(auxv, AuxRole::RmsNormOutLimbHiPairs),
            out_limb_hi_mult: take(auxv, AuxRole::RmsNormOutLimbHiMultiplicity),
        };
        let make = |m: usize, d: usize, n_real: usize, identity: bool|
            -> Option<(Store, T, T, T, TrustedModelManifest)> {
            let mut st = Store::new();
            let len = m * d;
            let xv: Vec<Goldilocks> = (0..len)
                .map(|i| from_i64(((i as i64 * 11) % 19) - 9)).collect();
            let wv: Vec<Goldilocks> = (0..len)
                .map(|i| from_i64(((i as i64 * 3) % 7) + 1)).collect();
            let x = st.push(xv);
            let w = st.push(wv);
            let out = st.push(vec![Goldilocks::ZERO; len]);
            let rsqrt_t = st.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
            let limb_v: Vec<Goldilocks> = if identity {
                (0..65536).map(|i| from_i64(i as i64)).collect()
            } else {
                (0..65536).map(|i| from_i64((65535 - i) as i64)).collect()
            };
            let limb_t = st.push(limb_v);
            let ops = vec![Op::RmsNorm { x, w, out, rsqrt_table: rsqrt_t,
                limb_table: limb_t, m, d, n_real }];
            forward_ops(&mut st, &ops);
            let model = TrustedModelManifest::from_offline_commitment(
                &[], &st.owned_slices(), &ops);
            Some((st, x, w, out, model))
        };

        // m >= 32 and n_real == d.
        let (st, _x, _w, out, model) = make(32, 8, 8, true).unwrap();
        let ops = vec![Op::RmsNorm { x: _x, w: _w, out,
            rsqrt_table: 0, limb_table: 0, m: 32, d: 8, n_real: 8 }];
        // Rebuild the op with the real table ids from the store layout.
        // (The forward already ran; take the ids from the fixture.)
        let (x_id, w_id) = (_x, _w);
        let (rsqrt_id, limb_id) = {
            let mut ids = (0, 0);
            for (i, t) in st.v.iter().enumerate() {
                if let TensorData::Owned(v) = t {
                    if v.len() == 32 { ids.0 = i; }
                    if v.len() == 65536 { ids.1 = i; }
                }
            }
            ids
        };
        let ops = vec![Op::RmsNorm { x: x_id, w: w_id, out, rsqrt_table: rsqrt_id,
            limb_table: limb_id, m: 32, d: 8, n_real: 8 }];
        let mut auxv = prepare_rms_norm_aux(&st, &ops, &model).expect("m32 aux");
        let point: Vec<Ef> = (0..(32usize * 8).trailing_zeros())
            .map(|b| ef_u64(3 + b as u64)).collect();
        let value = ef_eval(st.get(out), &point);
        let auxp = build_aux(&mut auxv);
        let (proof, claims) = prove_reverse_rms_norm(
            &st, &ops[0], &point, value, auxp, &model,
            &mut Transcript::new(b"rms-low-m32"), None).expect("m32 proof");
        assert_eq!(claims.len(), 3);
        let mut auxv2 = prepare_rms_norm_aux(&st, &ops, &model).unwrap();
        let fill = |v: &mut Vec<PreparedAux>| {
            let mut a = Vec::new();
            for role in [AuxRole::RmsNormRowWitness, AuxRole::RmsNormOutWitness,
                AuxRole::RmsNormRsqrtPairs, AuxRole::RmsNormRsqrtMultiplicity,
                AuxRole::RmsNormLimbLoPairs, AuxRole::RmsNormLimbLoMultiplicity,
                AuxRole::RmsNormLimbHiPairs, AuxRole::RmsNormLimbHiMultiplicity,
                AuxRole::RmsNormOutLimbLoPairs, AuxRole::RmsNormOutLimbLoMultiplicity,
                AuxRole::RmsNormOutLimbHiPairs, AuxRole::RmsNormOutLimbHiMultiplicity] {
                a.push(take(v, role).descriptor);
            }
            a
        };
        let dsc = fill(&mut auxv2);
        let refs = RmsAuxRefs {
            row: &dsc[0], out: &dsc[1], rsqrt_pairs: &dsc[2], rsqrt_mult: &dsc[3],
            limb_lo_pairs: &dsc[4], limb_lo_mult: &dsc[5],
            limb_hi_pairs: &dsc[6], limb_hi_mult: &dsc[7],
            out_limb_lo_pairs: &dsc[8], out_limb_lo_mult: &dsc[9],
            out_limb_hi_pairs: &dsc[10], out_limb_hi_mult: &dsc[11],
        };
        assert!(verify_reverse_rms_norm(&ops[0], &point, value, refs, &model,
            &proof, &mut Transcript::new(b"rms-low-m32"), None).is_some());

        // Non-identity limb table must fail closed at aux preparation.
        let (st2, x2, w2, out2, model2) = make(4, 8, 5, false).unwrap();
        let ops2 = vec![Op::RmsNorm { x: x2, w: w2, out: out2,
            rsqrt_table: 2, limb_table: 3, m: 4, d: 8, n_real: 5 }];
        assert!(prepare_rms_norm_aux(&st2, &ops2, &model2).is_none(),
            "non-identity limb table must fail closed");

        // Out-of-range out limb and negative ms must fail closed at prove.
        let (st3, x3, w3, out3, model3) = make(4, 8, 5, true).unwrap();
        let (rsqrt3, limb3) = {
            let mut ids = (0, 0);
            for (i, t) in st3.v.iter().enumerate() {
                if let TensorData::Owned(v) = t {
                    if v.len() == 32 { ids.0 = i; }
                    if v.len() == 65536 { ids.1 = i; }
                }
            }
            ids
        };
        let ops3 = vec![Op::RmsNorm { x: x3, w: w3, out: out3,
            rsqrt_table: rsqrt3, limb_table: limb3, m: 4, d: 8, n_real: 5 }];
        let p3: Vec<Ef> = (0..(4usize * 8).trailing_zeros()).map(|b| ef_u64(5 + b as u64)).collect();
        let v3 = ef_eval(st3.get(out3), &p3);
        let mut auxbad = prepare_rms_norm_aux(&st3, &ops3, &model3).unwrap();
        {
            let pos = auxbad.iter().position(|p| p.descriptor.role == AuxRole::RmsNormOutWitness).unwrap();
            auxbad[pos].columns[3][0] += Goldilocks::from_u64(65536);
        }
        let badp = build_aux(&mut auxbad);
        assert!(prove_reverse_rms_norm(&st3, &ops3[0], &p3, v3, badp, &model3,
            &mut Transcript::new(b"rms-low-badlimb"), None).is_none());
        let mut auxneg = prepare_rms_norm_aux(&st3, &ops3, &model3).unwrap();
        {
            let pos = auxneg.iter().position(|p| p.descriptor.role == AuxRole::RmsNormRowWitness).unwrap();
            auxneg[pos].columns[RMS_MS][0] = from_i64(-1);
        }
        let negp = build_aux(&mut auxneg);
        assert!(prove_reverse_rms_norm(&st3, &ops3[0], &p3, v3, negp, &model3,
            &mut Transcript::new(b"rms-low-negms"), None).is_none());
    }

    /// LNC (6th B1 op): honest direct roundtrip + bound/pooled roundtrip.
    #[test]
    fn b1_lnc_reverse_roundtrip() {
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len).map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len).map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let bv: Vec<Goldilocks> = (0..len).map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x = store.push(xv.clone());
        let w = store.push(wv.clone());
        let b = store.push(bv.clone());
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![Op::LayerNormCentered { x, w, b, out, rsqrt_table: rsqrt_t,
            m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops,
            "/tmp/zkie-lnc-roundtrip");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        // B2 gate: public execution extraction must accept the LNC op.
        let pub_exec = crate::bundle::public_execution(&store, &ops, &cached, &model)
            .expect("B2 public execution must accept LNC");
        assert!(pub_exec.inputs.contains_key(&x));
        assert!(pub_exec.outputs.contains_key(&out));
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let mut auxv = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux");
        let descs = [
            take(&mut auxv, AuxRole::LncRowWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncOutWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtMultiplicity).descriptor.clone(),
        ];
        let point: Vec<Ef> = (0..len.trailing_zeros()).map(|i| ef_u64(2 + i as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let mut auxall = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux2");
        let auxp = LncAux {
            row: take(&mut auxall, AuxRole::LncRowWitness),
            out: take(&mut auxall, AuxRole::LncOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::LncRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::LncRsqrtMultiplicity),
        };
        let mut tp = Transcript::new(b"b1-lnc");
        let (proof, claims) = prove_reverse_lnc(
            &store, &ops[0], &point, value, auxp, &model, &mut tp, None)
            .expect("lnc proof");
        assert_eq!(claims.len(), 5);
        let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
            rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
        let mut tv = Transcript::new(b"b1-lnc");
        assert!(verify_reverse_lnc(&ops[0], &point, value, refs, &model,
            &proof, &mut tv, None).is_some(), "honest LNC must verify");
        let mut tv = Transcript::new(b"b1-lnc");
        assert!(verify_reverse_lnc(&ops[0], &point, value + Ef::ONE, refs, &model,
            &proof, &mut tv, None).is_none());

        // Bound/pooled path: x is the only execution input; w/b are weights.
        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::new_testing(5);
        let proof2 = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("lnc bound proof");
        let budget = proof_budget(&proof2, &proof2.aux, &ops, &model).expect("budget");
        assert!(budget.openings <= MAX_EFFECTIVE_OPENINGS,
            "LNC pooled K={} exceeds cap", budget.openings);
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof2,
            &PublicStatement::Generic, &model, &execution), "LNC bound proof must verify");
        eprintln!("LNC bound K={}", budget.openings);
    }

    /// LNC edge cases for the mean/var truncation: n_real=1 (zero mean-bit
    /// width) and n_real=d (all columns real). Direct roundtrip each.
    #[test]
    fn lnc_edge_n_real_roundtrip() {
        for &n_real in &[1usize, 8usize] {
            let mut store = Store::new();
            let (m, d) = (4usize, 8usize);
            let len = m * d;
            let xv: Vec<Goldilocks> = (0..len)
                .map(|i| from_i64(((i as i64 * 11) % 13) - 6)).collect();
            let wv: Vec<Goldilocks> = (0..len)
                .map(|i| from_i64(((i as i64 * 3) % 7) + 1)).collect();
            let bv: Vec<Goldilocks> = (0..len)
                .map(|i| from_i64(((i as i64 * 2) % 3) - 1)).collect();
            let x = store.push(xv);
            let w = store.push(wv);
            let b = store.push(bv);
            let out = store.push(vec![Goldilocks::ZERO; len]);
            let rsqrt_t = store.push(
                (0..32).map(|i| from_i64(1000 + i as i64)).collect());
            let ops = vec![Op::LayerNormCentered { x, w, b, out,
                rsqrt_table: rsqrt_t, m, d, n_real }];
            forward_ops(&mut store, &ops);
            let cached = commit_model_weights(&store, &ops,
                &format!("/tmp/zkie-lnc-edge-{n_real}"));
            let model = TrustedModelManifest::from_offline_commitment(
                &cached, &store.owned_slices(), &ops);
            let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
                let p = v.iter().position(|q| q.descriptor.role == role).unwrap();
                v.remove(p)
            };
            let mut auxv = prepare_lnc_aux(&store, &ops, &model).unwrap();
            let descs = [
                take(&mut auxv, AuxRole::LncRowWitness).descriptor.clone(),
                take(&mut auxv, AuxRole::LncOutWitness).descriptor.clone(),
                take(&mut auxv, AuxRole::LncRsqrtPairs).descriptor.clone(),
                take(&mut auxv, AuxRole::LncRsqrtMultiplicity).descriptor.clone(),
            ];
            let point: Vec<Ef> = (0..len.trailing_zeros())
                .map(|i| ef_u64(2 + i as u64)).collect();
            let value = ef_eval(store.get(out), &point);
            let mut auxall = prepare_lnc_aux(&store, &ops, &model).unwrap();
            let auxp = LncAux {
                row: take(&mut auxall, AuxRole::LncRowWitness),
                out: take(&mut auxall, AuxRole::LncOutWitness),
                rsqrt_pairs: take(&mut auxall, AuxRole::LncRsqrtPairs),
                rsqrt_mult: take(&mut auxall, AuxRole::LncRsqrtMultiplicity),
            };
            let mut tp = Transcript::new(b"lnc-edge");
            let (proof, _claims) = prove_reverse_lnc(
                &store, &ops[0], &point, value, auxp, &model, &mut tp, None)
                .unwrap_or_else(|| panic!("edge n_real={n_real} proof"));
            let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
                rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
            let mut tv = Transcript::new(b"lnc-edge");
            assert!(verify_reverse_lnc(&ops[0], &point, value, refs, &model,
                &proof, &mut tv, None).is_some(),
                "edge n_real={n_real} must verify");
            let mut tv = Transcript::new(b"lnc-edge");
            assert!(verify_reverse_lnc(&ops[0], &point, value + Ef::ONE,
                refs, &model, &proof, &mut tv, None).is_none(),
                "edge n_real={n_real} forged value accepted");
        }
    }

    /// M4: two LNC ops sharing one rsqrt table produce ONE per-table batch
    /// opening (not two), the pooled proof verifies, and the budget charges a
    /// single internal-table opening.
    #[test]
    fn m4_lnc_shared_table_batch_roundtrip() {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let mk = |off: i64| -> Vec<Goldilocks> {
            (0..len).map(|i| from_i64(((i as i64 * 7 + off) % 17) - 8)).collect()
        };
        let x1v = mk(0); let x2v = mk(3);
        let w1v: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let w2v: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 7) + 1)).collect();
        let b1v: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 2) % 5) - 2)).collect();
        let b2v: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x1 = store.push(x1v.clone());
        let x2 = store.push(x2v.clone());
        let w1 = store.push(w1v);
        let w2 = store.push(w2v);
        let b1 = store.push(b1v);
        let b2 = store.push(b2v);
        let out1 = store.push(vec![Goldilocks::ZERO; len]);
        let out2 = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![
            Op::LayerNormCentered { x: x1, w: w1, b: b1, out: out1,
                rsqrt_table: rsqrt_t, m, d, n_real },
            Op::LayerNormCentered { x: x2, w: w2, b: b2, out: out2,
                rsqrt_table: rsqrt_t, m, d, n_real },
        ];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-m4-lnc");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let execution = TrustedExecution {
            inputs: [(x1, x1v), (x2, x2v)].into(),
            outputs: [(out1, store.get(out1).to_vec()),
                      (out2, store.get(out2).to_vec())].into(),
        };
        let whir = Whir::new_testing(5);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("M4 shared-table bound proof");
        assert_eq!(proof.internal_table_openings.len(), 0,
            "M4b: shared rsqrt joins the group; no per-table batch opening");
        let budget = proof_budget(&proof, &proof.aux, &ops, &model).expect("budget");
        let ub = opening_upper_bound(&ops, &model).expect("upper bound");
        assert!(budget.openings <= ub,
            "actual K={} exceeds verifier upper bound {ub}", budget.openings);
        assert!(budget.openings <= MAX_EFFECTIVE_OPENINGS,
            "M4 shared-table K={} exceeds cap", budget.openings);
        let mut lnc_steps = 0usize;
        for step in &proof.reverse.steps {
            if let ReverseReduction::Lnc { proof } = &step.reduction {
                lnc_steps += 1;
                assert!(proof.rsqrt.table_opening.is_none(),
                    "pooled LNC must defer the table opening");
            }
        }
        assert_eq!(lnc_steps, 2);
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution),
            "M4 shared-table proof must verify");
        let mut bad = proof;
        let mut hit = false;
        for step in &mut bad.reverse.steps {
            if let ReverseReduction::LookupGroups { groups } = &mut step.reduction {
                groups[0].identity.final_evals[0] += Ef::ONE;
                hit = true;
            }
        }
        assert!(hit, "LNC rsqrt must be in the shared group proof");
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &bad,
            &PublicStatement::Generic, &model, &execution),
            "tampered shared rsqrt group must be rejected");
    }

    /// M4: two Softmax ops sharing one exp table produce one batch table
    /// opening and verify through the bound entry.
    #[test]
    fn m4_softmax_shared_table_batch_roundtrip() {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let (m, n) = (4usize, 8usize);
        let len = m * n;
        let table = store.push((0..32)
            .map(|i| from_i64(10842 + (i % 2) as i64)).collect());
        let idx1 = store.push_idx((0..len)
            .map(|i| [1u32, 1, 1, 1, 1, 0, 0, 0][i % 8]).collect());
        let idx2 = store.push_idx((0..len)
            .map(|i| [0u32, 1, 1, 1, 0, 1, 0, 1][i % 8]).collect());
        let e1 = store.push(vec![Goldilocks::ZERO; len]);
        let e2 = store.push(vec![Goldilocks::ZERO; len]);
        let out1 = store.push(vec![Goldilocks::ZERO; len]);
        let out2 = store.push(vec![Goldilocks::ZERO; len]);
        let ops = vec![
            Op::Softmax { idx: idx1, e: e1, out: out1, table, m, n },
            Op::Softmax { idx: idx2, e: e2, out: out2, table, m, n },
        ];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-m4-softmax");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx1, len), (idx2, len)].into());
        let idx_g = |id: usize| -> Vec<Goldilocks> {
            store.idx[id].iter().map(|&x| Goldilocks::from_u64(x as u64)).collect()
        };
        let execution = TrustedExecution {
            inputs: [(TensorKey::Index(idx1).encoded().unwrap(), idx_g(idx1)),
                     (TensorKey::Index(idx2).encoded().unwrap(), idx_g(idx2))].into(),
            outputs: [(out1, store.get(out1).to_vec()),
                      (out2, store.get(out2).to_vec())].into(),
        };
        let whir = Whir::new_testing(5);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("M4 softmax shared-table bound proof");
        eprintln!("M4 softmax table openings = {}", proof.internal_table_openings.len());
        assert_eq!(proof.internal_table_openings.len(), 0,
            "M4b: Softmax exp joins the shared group; no per-table batch opening");
        let budget = proof_budget(&proof, &proof.aux, &ops, &model).expect("budget");
        assert!(budget.openings <= MAX_EFFECTIVE_OPENINGS,
            "M4 softmax shared-table K={} exceeds cap", budget.openings);
        let mut sm_steps = 0usize;
        for step in &proof.reverse.steps {
            if let ReverseReduction::Softmax { proof } = &step.reduction {
                sm_steps += 1;
                assert!(proof.lookup.table_opening.is_none(),
                    "pooled Softmax must defer the table opening");
            }
        }
        assert_eq!(sm_steps, 2);
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution),
            "M4 softmax shared-table proof must verify");
        let mut bad = proof;
        let mut hit = false;
        for step in &mut bad.reverse.steps {
            if let ReverseReduction::LookupGroups { groups } = &mut step.reduction {
                groups[0].identity.final_evals[0] += Ef::ONE;
                hit = true;
            }
        }
        assert!(hit, "Softmax exp must be in the shared group proof");
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &bad,
            &PublicStatement::Generic, &model, &execution),
            "tampered shared exp group must be rejected");
    }

    /// P1 Phase 2: the Softmax exp table as an A table. The internal lookup
    /// uses the digest-verified caller values, produces no table opening, and
    /// leaves the lookup groups empty (A tables are not PCS-committed).
    #[test]
    fn p1_a_table_softmax_internal_lookup_no_opening() {
        use crate::tables::{hash_a_table, LoadedATables};
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let (m, n) = (4usize, 8usize);
        let len = m * n;
        let table_vals: Vec<Goldilocks> = (0..32)
            .map(|i| from_i64(10842 + (i % 2) as i64)).collect();
        let table = store.push(table_vals.clone());
        let idx = store.push_idx((0..len)
            .map(|i| [1u32, 1, 1, 1, 1, 0, 0, 0][i % 8]).collect());
        let e = store.push(vec![Goldilocks::ZERO; len]);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let ops = vec![Op::Softmax { idx, e, out, table, m, n }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-p1-a-softmax");
        let mut model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, len)].into());
        let digest = hash_a_table(table, 32, 5, &table_vals);
        let entries = [(table, ATableEntry {
            kind: ATableKind::File, length: 32, arity: 5,
            file_path: Some("exp.bin".to_string()), digest: Some(digest),
        })].into_iter().collect();
        let values = [(table, std::sync::Arc::new(table_vals.clone()))].into_iter().collect();
        let digests = [(table, digest)].into_iter().collect();
        LoadedATables { entries, values, digests }.install(&mut model).expect("install A");
        let groups = static_lookup_groups(&ops, &model).unwrap();
        assert_eq!(groups.len(), 1);
        assert!(groups.contains_key(&table));
        assert!(internal_lookup_member_counts(&ops, &model).is_empty());
        let idx_g: Vec<Goldilocks> = store.idx[idx].iter()
            .map(|&x| Goldilocks::from_u64(x as u64)).collect();
        let execution = TrustedExecution {
            inputs: [(TensorKey::Index(idx).encoded().unwrap(), idx_g)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = Whir::new_testing(5);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("A Softmax proof");
        assert!(proof.internal_table_openings.is_empty(), "A exp must not open");
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution));
        let mut bad = model.clone();
        std::sync::Arc::make_mut(bad.a_table_values.get_mut(&table).unwrap())[1] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &bad, &execution),
            "changed exp values must be rejected");
    }

    /// AUDIT (LNC): a malicious prover keeps the honest virtual proofs and
    /// commits to the honest out witness, but forges the caller's output
    /// value with a same_poly bind over an interpolating fake polynomial
    /// f' = out + a*chi0 + b*chi1. Because the out witness is committed
    /// before the challenge and the merged claim is opened at the merged
    /// point, verification must reject.
    #[test]
    fn audit_lnc_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let bv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x = store.push(xv);
        let w = store.push(wv);
        let b = store.push(bv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![Op::LayerNormCentered { x, w, b, out,
            rsqrt_table: rsqrt_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops,
            "/tmp/zkie-lnc-attack");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let mut auxv = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux");
        let descs = [
            take(&mut auxv, AuxRole::LncRowWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncOutWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtMultiplicity).descriptor.clone(),
        ];
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|i| ef_u64(2 + i as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let mut auxall = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux2");
        let auxp = LncAux {
            row: take(&mut auxall, AuxRole::LncRowWitness),
            out: take(&mut auxall, AuxRole::LncOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::LncRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::LncRsqrtMultiplicity),
        };
        let mut tp = Transcript::new(b"audit-lnc");
        let (proof, _claims) = prove_reverse_lnc(
            &store, &ops[0], &point, genuine, auxp, &model, &mut tp, None)
            .expect("honest proof");

        // Replay the verifier transcript up to the bind.
        let (_, _, _, _, rsqrt_id, mm, dd, nn) = lnc_dims(&ops[0]).unwrap();
        let lgl = len.trailing_zeros() as usize;
        let lg_d = d.trailing_zeros() as usize;
        let lg_m = m.trailing_zeros() as usize;
        let arity = rms_row_arity(m).unwrap();
        let lay = lnc_row_layout(n_real).unwrap();
        let rsqrt_len = model.lookup_lengths[&rsqrt_id];
        let mut t = Transcript::new(b"audit-lnc");
        t.absorb(&bincode::serialize(&descs[1].commitment).unwrap());
        t.absorb(b"zkie-lnc-v1");
        t.absorb_u64(mm as u64); t.absorb_u64(dd as u64);
        t.absorb_u64(nn as u64); t.absorb_u64(rsqrt_len as u64);
        let _u_row = t.ef_field_vec(arity);
        let g_row = t.ef_field();
        let g_mean_row = t.ef_field();
        let row_terms = lnc_row_terms(g_row, g_mean_row, n_real, &lay);
        let (ok, _z_row, _) = efo::verify_virtual(&proof.row, &row_terms,
            Ef::ZERO, arity, &mut t);
        assert!(ok);
        let _u_mean = t.ef_field_vec(lg_m);
        let mean_terms = lnc_mean_terms(d);
        let (ok, _z_mean, _) = efo::verify_virtual(&proof.mean, &mean_terms,
            Ef::ZERO, lgl, &mut t);
        assert!(ok);
        let _u_var = t.ef_field_vec(lg_m);
        let var_terms = lnc_var_terms(n_real);
        let (ok, _z_var, _) = efo::verify_virtual(&proof.var, &var_terms,
            Ef::ZERO, lgl, &mut t);
        assert!(ok);
        let _q_out = t.ef_field_vec(lgl);
        let g1 = t.ef_field();
        let g2 = t.ef_field();
        let g3 = t.ef_field();
        let out_terms = lnc_out_full_terms(g1, g2, g3);
        let (ok, z_out, _) = efo::verify_virtual(&proof.out, &out_terms,
            Ef::ZERO, lgl, &mut t);
        assert!(ok);
        let fo = proof.out.final_evals.clone();

        // f' = out + a*chi0 + b*chi1 with f'(point)=forged, f'(z_out)=fo[6].
        let out_ef = ef_lift(store.get(out));
        let delta = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z_out).unwrap();
        let v11 = efo::eq_poly(&u1, &z_out).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = delta * v11 * det.inverse();
        let bb = -delta * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..len)
            .map(|i| out_ef[i] + a * chi0[i] + bb * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z_out.clone(), fo[6])], &mut t).0;

        // Regenerate the post-bind rsqrt lookup under the forged transcript.
        let mut auxatk = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux3");
        let rsqrt_pairs = take(&mut auxatk, AuxRole::LncRsqrtPairs);
        let rsqrt_mult = take(&mut auxatk, AuxRole::LncRsqrtMultiplicity);
        let mut p_out = z_out[lg_d..].to_vec();
        p_out.resize(arity, Ef::ZERO);
        let rsqrt_xs: Vec<u32> = (0..m)
            .map(|r| to_i64(rsqrt_pairs.columns[0][r]) as u32).collect();
        let rsqrt_ys: Vec<Goldilocks> = (0..m)
            .map(|r| rsqrt_pairs.columns[1][r]).collect();
        let rsqrt_atk = internal_lookup_prove(&store, rsqrt_id, rsqrt_pairs,
            rsqrt_mult, 0, 1, &rsqrt_xs, &rsqrt_ys, &p_out, fo[3],
            &model, &mut t, None).expect("rsqrt atk");

        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        forged_proof.rsqrt = rsqrt_atk;
        let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
            rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
        let mut tv = Transcript::new(b"audit-lnc");
        let got = verify_reverse_lnc(&ops[0], &point, forged, refs, &model,
            &forged_proof, &mut tv, None);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged LNC output claim was ACCEPTED");
    }

    /// AUDIT RED->GREEN (LNC rho binding): forge mean+1 and sum_x+n in the
    /// row aux, use fake mean/var prefix-selector virtuals (the prover hook
    /// solves for the constant rho shift that zeroes each sumcheck), and
    /// recompute the committed out witness/out column accordingly. Without
    /// the rho final-eval checks this proof is accepted; with them it must
    /// be rejected.
    #[test]
    fn audit_lnc_forged_rho_must_reject() {
        fn recommit(p: &mut PreparedAux) {
            let refs: Vec<&[Goldilocks]> = p.columns.iter().map(Vec::as_slice).collect();
            let padded = 1usize << p.descriptor.arity;
            let vars = p.descriptor.columns.checked_mul(padded).unwrap()
                .checked_next_power_of_two().unwrap().trailing_zeros() as usize;
            let pow = zkie_core::pcs::whir::Whir::required_pow_bits(vars, VERIFIER_SECURITY);
            let whir = zkie_core::pcs::whir::Whir::with_params(
                p.descriptor.arity, VERIFIER_SECURITY, pow);
            let (commitment, prover_data, protocol, whir) = whir.commit_batch(&refs);
            p.descriptor.commitment = commitment;
            p.prover_data = prover_data;
            p.protocol = protocol;
            p.whir = whir;
        }
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let bv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x = store.push(xv.clone());
        let w = store.push(wv.clone());
        let b = store.push(bv.clone());
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![Op::LayerNormCentered { x, w, b, out,
            rsqrt_table: rsqrt_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-lnc-forged-rho");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let lay = lnc_row_layout(n_real).unwrap();
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let p = v.iter().position(|q| q.descriptor.role == role).unwrap();
            v.remove(p)
        };
        let mut auxall = prepare_lnc_aux(&store, &ops, &model).unwrap();
        let mut auxp = LncAux {
            row: take(&mut auxall, AuxRole::LncRowWitness),
            out: take(&mut auxall, AuxRole::LncOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::LncRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::LncRsqrtMultiplicity),
        };
        // Forge mean+1, sum_x+n for every real row, with consistent bounded
        // mean decomposition.
        let n = n_real as i64;
        let mut row_mean = vec![0i64; m];
        for r in 0..m {
            let mean0 = to_i64(auxp.row.columns[lay.mean][r]);
            let sum0 = to_i64(auxp.row.columns[lay.sum_x][r]);
            let mean1 = mean0 + 1;
            row_mean[r] = mean1;
            auxp.row.columns[lay.mean][r] = from_i64(mean1);
            auxp.row.columns[lay.sum_x][r] = from_i64(sum0 + n);
            let shifted = mean1 + (1i64 << 15);
            let raw = shifted.div_euclid(1i64 << LNC_MEAN_RAW_BITS);
            let rem = shifted.rem_euclid(1i64 << LNC_MEAN_RAW_BITS);
            auxp.row.columns[lay.raw_mean][r] = from_i64(raw);
            auxp.row.columns[lay.rem_raw_mean][r] = from_i64(rem);
            let raw_off = (raw + (1i64 << 15)) as u64;
            for j in 0..LNC_MEAN_RAW_BITS {
                auxp.row.columns[lay.raw_mean_bits + j][r] =
                    Goldilocks::from_u64((raw_off >> j) & 1);
            }
            for j in 0..LNC_MEAN_REM_BITS {
                auxp.row.columns[lay.rem_raw_mean_bits + j][r] =
                    Goldilocks::from_u64(((rem as u64) >> j) & 1);
            }
        }
        // Recompute the out witness for the forged mean (same honest rstd).
        let mut forged_out = vec![Goldilocks::ZERO; len];
        for i in 0..len {
            let row = i / d;
            let rstd = to_i64(auxp.row.columns[RMS_RSTD][row]);
            let raw = (to_i64(xv[i]) - row_mean[row]).checked_mul(rstd).unwrap()
                .checked_mul(to_i64(wv[i])).unwrap();
            let o = round_div(raw, 1i64 << 32);
            let out_v = o + to_i64(bv[i]);
            let rem = raw - o.checked_mul(1i64 << 32).unwrap() + (1i64 << 31);
            let ob = o + (1i64 << 31);
            assert!(rem >= 0 && rem < (1i64 << 32));
            assert!(ob >= 0 && ob < (1i64 << 32));
            let rem_lo = rem & 0xFFFF;
            let rem_hi = rem >> 16;
            let olo = ob & 0xFFFF;
            let ohi = ob >> 16;
            forged_out[i] = from_i64(out_v);
            auxp.out.columns[LNC_OUT][i] = from_i64(out_v);
            auxp.out.columns[LNC_REM_LO][i] = from_i64(rem_lo);
            auxp.out.columns[LNC_REM_HI][i] = from_i64(rem_hi);
            auxp.out.columns[LNC_O_LO][i] = from_i64(olo);
            auxp.out.columns[LNC_O_HI][i] = from_i64(ohi);
            for j in 0..LNC_LIMB_BITS {
                auxp.out.columns[LNC_BITS + j][i] =
                    Goldilocks::from_u64(((rem_lo as u64) >> j) & 1);
                auxp.out.columns[LNC_BITS + LNC_LIMB_BITS + j][i] =
                    Goldilocks::from_u64(((rem_hi as u64) >> j) & 1);
                auxp.out.columns[LNC_BITS + 2 * LNC_LIMB_BITS + j][i] =
                    Goldilocks::from_u64(((olo as u64) >> j) & 1);
                auxp.out.columns[LNC_BITS + 3 * LNC_LIMB_BITS + j][i] =
                    Goldilocks::from_u64(((ohi as u64) >> j) & 1);
            }
        }
        store.v[out] = TensorData::Owned(forged_out);
        recommit(&mut auxp.row);
        recommit(&mut auxp.out);
        let descs = [auxp.row.descriptor.clone(), auxp.out.descriptor.clone(),
            auxp.rsqrt_pairs.descriptor.clone(), auxp.rsqrt_mult.descriptor.clone()];
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|i| ef_u64(2 + i as u64)).collect();
        let forged_value = ef_eval(store.get(out), &point);
        let mut tp = Transcript::new(b"audit-lnc-rho");
        let (proof, _claims, _roots) = prove_reverse_lnc_impl(
            &store, &ops[0], &point, forged_value, auxp, &model, None, &mut tp,
            None, true, false).expect("forged rho proof");
        let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
            rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
        let mut tv = Transcript::new(b"audit-lnc-rho");
        assert!(verify_reverse_lnc(&ops[0], &point, forged_value, refs, &model,
            &proof, &mut tv, None).is_none(),
            "AUDIT FAILURE: forged LNC rho proof was ACCEPTED");
    }

    /// LNC at a real-model shape: GPT-2/TimesFM hidden width with
    /// n_real != d (768 real columns of 1024), m = 16 rows. Exercises the
    /// mean/var truncation with a non-power-of-two n_real, the per-row
    /// rsqrt-index piecewise map at scale, the committed 69-column out
    /// witness, and the pooled budget cap.
    #[test]
    fn lnc_real_shape_roundtrip_pooled() {
        let mut store = Store::new();
        let (m, d, n_real) = (16usize, 1024usize, 768usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let bv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x = store.push(xv.clone());
        let w = store.push(wv);
        let b = store.push(bv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![Op::LayerNormCentered { x, w, b, out,
            rsqrt_table: rsqrt_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-lnc-gpt2shape");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let p = v.iter().position(|q| q.descriptor.role == role).unwrap();
            v.remove(p)
        };
        let mut auxv = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux");
        let descs = [
            take(&mut auxv, AuxRole::LncRowWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncOutWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtMultiplicity).descriptor.clone(),
        ];
        let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
            rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|i| ef_u64(2 + i as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let mut auxall = prepare_lnc_aux(&store, &ops, &model).expect("lnc aux2");
        let auxp = LncAux {
            row: take(&mut auxall, AuxRole::LncRowWitness),
            out: take(&mut auxall, AuxRole::LncOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::LncRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::LncRsqrtMultiplicity),
        };
        let mut tp = Transcript::new(b"lnc-gpt2shape");
        let (proof, claims) = prove_reverse_lnc(
            &store, &ops[0], &point, value, auxp, &model, &mut tp, None)
            .expect("lnc real-shape proof");
        assert_eq!(claims.len(), 5);
        let mut tv = Transcript::new(b"lnc-gpt2shape");
        assert!(verify_reverse_lnc(&ops[0], &point, value, refs, &model,
            &proof, &mut tv, None).is_some(), "real-shape direct verify");

        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::new_testing(5);
        let proof2 = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("lnc real-shape bound proof");
        let budget = proof_budget(&proof2, &proof2.aux, &ops, &model).expect("budget");
        assert!(budget.openings <= MAX_EFFECTIVE_OPENINGS,
            "real-shape LNC K={} exceeds cap", budget.openings);
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof2,
            &PublicStatement::Generic, &model, &execution),
            "real-shape pooled LNC verify");
        eprintln!("LNC real-shape K={}", budget.openings);
    }

    /// LNC tamper matrix: (a) the prover refuses any aux witness that does not
    /// match the trusted forward semantics (mean / sum_x / rem_mean, centered
    /// variance / remainder / rsqrt / index, out limbs / bits / value, rsqrt
    /// pairs / multiplicity); (b) the verifier rejects mutated virtual final
    /// evaluations (mean, var, out, bits, limbs) and a mutated index; (c) the
    /// pooled bound verifier rejects a mutated LNC step.
    #[test]
    fn lnc_tamper_matrix_must_reject() {
        fn pos(v: &[PreparedAux], role: AuxRole) -> usize {
            v.iter().position(|p| p.descriptor.role == role).unwrap()
        }
        fn bump(v: &mut Vec<PreparedAux>, role: AuxRole, col: usize) {
            let p = pos(v, role);
            v[p].columns[col][0] = v[p].columns[col][0] + Goldilocks::ONE;
        }
        fn flip(v: &mut Vec<PreparedAux>, role: AuxRole, col: usize) {
            let p = pos(v, role);
            v[p].columns[col][0] = if to_i64(v[p].columns[col][0]) == 0 {
                Goldilocks::ONE
            } else { Goldilocks::ZERO };
        }
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let bv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 3) % 5) - 2)).collect();
        let x = store.push(xv.clone());
        let w = store.push(wv);
        let b = store.push(bv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let ops = vec![Op::LayerNormCentered { x, w, b, out,
            rsqrt_table: rsqrt_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cached = commit_model_weights(&store, &ops, "/tmp/zkie-lnc-tamper");
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let lay = lnc_row_layout(n_real).unwrap();
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|i| ef_u64(2 + i as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let p = v.iter().position(|q| q.descriptor.role == role).unwrap();
            v.remove(p)
        };
        let run_prove = |mutate: &dyn Fn(&mut Vec<PreparedAux>)| -> Option<ReverseLncProof> {
            let mut av = prepare_lnc_aux(&store, &ops, &model)?;
            mutate(&mut av);
            let auxp = LncAux {
                row: take(&mut av, AuxRole::LncRowWitness),
                out: take(&mut av, AuxRole::LncOutWitness),
                rsqrt_pairs: take(&mut av, AuxRole::LncRsqrtPairs),
                rsqrt_mult: take(&mut av, AuxRole::LncRsqrtMultiplicity),
            };
            let mut t = Transcript::new(b"lnc-tamper");
            prove_reverse_lnc(&store, &ops[0], &point, value, auxp, &model,
                &mut t, None).map(|(p, _)| p)
        };
        assert!(run_prove(&|_| {}).is_some(), "honest tamper baseline");
        let roww = AuxRole::LncRowWitness;
        let outw = AuxRole::LncOutWitness;
        let cases: Vec<(&str, Box<dyn Fn(&mut Vec<PreparedAux>)>)> = vec![
            ("mean", Box::new(|v| bump(v, roww, lay.mean))),
            ("sum_x", Box::new(|v| bump(v, roww, lay.sum_x))),
            ("rem_mean", Box::new(|v| bump(v, roww, lay.rem_mean))),
            ("var_ms", Box::new(|v| bump(v, roww, RMS_MS))),
            ("rem_var", Box::new(|v| bump(v, roww, RMS_REM_S))),
            ("rstd", Box::new(|v| bump(v, roww, RMS_RSTD))),
            ("sidx", Box::new(|v| bump(v, roww, RMS_SIDX))),
            ("rem_bits", Box::new(|v| flip(v, roww, lay.rem_bits))),
            ("delta_bits", Box::new(|v| flip(v, roww, lay.delta_bits))),
            ("mean_raw", Box::new(|v| bump(v, roww, lay.raw_mean))),
            ("mean_rem_raw", Box::new(|v| bump(v, roww, lay.rem_raw_mean))),
            ("mean_raw_bits", Box::new(|v| flip(v, roww, lay.raw_mean_bits))),
            ("mean_rem_bits", Box::new(|v| flip(v, roww, lay.rem_raw_mean_bits))),
            ("out", Box::new(|v| bump(v, outw, LNC_OUT))),
            ("rem_lo", Box::new(|v| bump(v, outw, LNC_REM_LO))),
            ("rem_hi", Box::new(|v| bump(v, outw, LNC_REM_HI))),
            ("o_lo", Box::new(|v| bump(v, outw, LNC_O_LO))),
            ("o_hi", Box::new(|v| bump(v, outw, LNC_O_HI))),
            ("out_bits", Box::new(|v| flip(v, outw, LNC_BITS))),
            ("rsqrt_pair", Box::new(|v| {
                let p = pos(v, AuxRole::LncRsqrtPairs);
                v[p].columns[1][0] = v[p].columns[1][0] + Goldilocks::ONE;
            })),
            ("rsqrt_mult", Box::new(|v| {
                let p = pos(v, AuxRole::LncRsqrtMultiplicity);
                v[p].columns[0][0] = v[p].columns[0][0] + Goldilocks::ONE;
            })),
        ];
        for (name, mutate) in cases {
            assert!(run_prove(mutate.as_ref()).is_none(), "prover accepted tampered {name}");
        }

        // Honest proof + descriptors for verifier tampering.
        let mut auxv = prepare_lnc_aux(&store, &ops, &model).unwrap();
        let descs = [
            take(&mut auxv, roww).descriptor.clone(),
            take(&mut auxv, outw).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::LncRsqrtMultiplicity).descriptor.clone(),
        ];
        let refs = LncAuxRefs { row: &descs[0], out: &descs[1],
            rsqrt_pairs: &descs[2], rsqrt_mult: &descs[3] };
        let honest = || -> ReverseLncProof {
            let mut av = prepare_lnc_aux(&store, &ops, &model).unwrap();
            let auxp = LncAux {
                row: take(&mut av, roww), out: take(&mut av, outw),
                rsqrt_pairs: take(&mut av, AuxRole::LncRsqrtPairs),
                rsqrt_mult: take(&mut av, AuxRole::LncRsqrtMultiplicity),
            };
            let mut t = Transcript::new(b"lnc-tamper-ok");
            prove_reverse_lnc(&store, &ops[0], &point, value, auxp, &model,
                &mut t, None).unwrap().0
        };
        let check = |mutate: &dyn Fn(&mut ReverseLncProof)| {
            let mut p = honest();
            mutate(&mut p);
            let mut t = Transcript::new(b"lnc-tamper-ok");
            verify_reverse_lnc(&ops[0], &point, value, refs, &model, &p, &mut t, None)
        };
        let mut base = honest();
        {
            let mut t = Transcript::new(b"lnc-tamper-ok");
            assert!(verify_reverse_lnc(&ops[0], &point, value, refs, &model,
                &base, &mut t, None).is_some(), "honest verifier baseline");
        }
        assert!(check(&|p| p.out.final_evals[6] = p.out.final_evals[6] + Ef::ONE).is_none(),
            "verifier accepted tampered out eval");
        assert!(check(&|p| p.out.final_evals[7] = p.out.final_evals[7] + Ef::ONE).is_none(),
            "verifier accepted tampered rem_lo eval");
        assert!(check(&|p| p.out.final_evals[8] = p.out.final_evals[8] + Ef::ONE).is_none(),
            "verifier accepted tampered rem_hi eval");
        assert!(check(&|p| p.out.final_evals[9] = p.out.final_evals[9] + Ef::ONE).is_none(),
            "verifier accepted tampered o_lo eval");
        assert!(check(&|p| p.out.final_evals[10] = p.out.final_evals[10] + Ef::ONE).is_none(),
            "verifier accepted tampered o_hi eval");
        assert!(check(&|p| p.out.final_evals[11] = Ef::ZERO).is_none(),
            "verifier accepted tampered ones eval");
        assert!(check(&|p| p.row.final_evals[1 + lay.mean] =
            p.row.final_evals[1 + lay.mean] + Ef::ONE).is_none(),
            "verifier accepted tampered row mean");
        assert!(check(&|p| p.row.final_evals[1 + RMS_MS] =
            p.row.final_evals[1 + RMS_MS] + Ef::ONE).is_none(),
            "verifier accepted tampered row ms");
        assert!(check(&|p| p.mean.final_evals[3] =
            p.mean.final_evals[3] + Ef::ONE).is_none(),
            "verifier accepted tampered sum_x eval");
        assert!(check(&|p| p.mean.final_evals[1] =
            p.mean.final_evals[1] + Ef::ONE).is_none(),
            "verifier accepted tampered mean rho eval");
        assert!(check(&|p| p.var.final_evals[1] =
            p.var.final_evals[1] + Ef::ONE).is_none(),
            "verifier accepted tampered var rho eval");
        assert!(check(&|p| p.var.final_evals[4] =
            p.var.final_evals[4] + Ef::ONE).is_none(),
            "verifier accepted tampered var eval");
        assert!(check(&|p| p.rsqrt.output_index =
            p.rsqrt.output_index + Ef::ONE).is_none(),
            "verifier accepted tampered rsqrt index");
        base.out.final_evals[6] = base.out.final_evals[6] + Ef::ONE;
        let mut t = Transcript::new(b"lnc-tamper-ok");
        assert!(verify_reverse_lnc(&ops[0], &point, value, refs, &model,
            &base, &mut t, None).is_none());

        // Pooled bound path: tampering the LNC step must fail closed.
        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::new_testing(5);
        let mut proof2 = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("lnc bound proof");
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof2,
            &PublicStatement::Generic, &model, &execution));
        let mut found = false;
        for step in &mut proof2.reverse.steps {
            if let ReverseReduction::Lnc { proof } = &mut step.reduction {
                proof.out.final_evals[6] = proof.out.final_evals[6] + Ef::ONE;
                found = true;
            }
        }
        assert!(found, "bound proof must contain an LNC step");
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof2,
            &PublicStatement::Generic, &model, &execution),
            "bound verifier accepted tampered LNC step");

        // validate_aux_descriptors: an LNC descriptor with the wrong column
        // count must fail closed even before any reverse step is replayed.
        let mut proof3 = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir,
            &cached, 0, 0, &PublicStatement::Generic, &model, &execution)
            .expect("lnc bound proof 3");
        let d = proof3.aux.iter_mut()
            .find(|a| a.role == AuxRole::LncOutWitness).unwrap();
        d.columns += 1;
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof3,
            &PublicStatement::Generic, &model, &execution),
            "validator accepted a tampered LNC aux descriptor");
    }

    /// O7-deep M1/M2 gate: the AuxPlan is deterministic and covers every aux
    /// column; per-arity group commitments open/verify; the synthetic
    /// multi-op RmsNorm graph's full pooled proof verifies under the
    /// 64-opening cap (RmsNorm is a migrated B1 role).
    #[test]
    fn o7_m2_pooled_aux_plan_and_group_opening() {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let x = store.push((0..len).map(|i| from_i64(((i as i64 * 7) % 17) - 8)).collect());
        let w = store.push((0..len).map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect());
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let limb_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let mut cur = x;
        let mut outs = Vec::new();
        let mut ops = Vec::new();
        for _ in 0..6 {
            let out = store.push(vec![Goldilocks::ZERO; len]);
            outs.push(out);
            ops.push(Op::RmsNorm { x: cur, w, out, rsqrt_table: rsqrt_t,
                limb_table: limb_t, m, d, n_real });
            cur = out;
        }
        forward_ops(&mut store, &ops);
        static O7M1_NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let uniq = O7M1_NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let cache = std::env::temp_dir().join(format!(
            "zkie-o7m1-{}-{}-{}", std::process::id(),
            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos()).unwrap_or(0), uniq));
        let cached = commit_model_weights(&store, &ops, cache.to_str().unwrap());
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);

        let plan = build_aux_plan(&ops, &model).expect("plan");
        let specs = aux_specs(&ops, &model).expect("specs");
        let total_cols: usize = specs.iter().map(|s| s.4).sum();
        assert_eq!(plan.slots.len(), total_cols, "plan must cover every aux column");
        assert_eq!(build_aux_plan(&ops, &model).unwrap().groups, plan.groups,
            "plan must be deterministic");
        let (_p2, groups, prepared_groups) = commit_aux_groups(&store, &ops, &model)
            .expect("group commitments");
        assert_eq!(groups.len(), plan.groups.len());
        assert!(validate_aux_plan(&ops, &model, &groups).is_some());
        let mut bad = groups.clone();
        bad[0].columns += 1;
        assert!(validate_aux_plan(&ops, &model, &bad).is_none(),
            "tampered group layout must be rejected");
        let mut bad = groups.clone();
        bad[0].layout_version += 1;
        assert!(validate_aux_plan(&ops, &model, &bad).is_none());

        // Pooled group opening: open one plan column at a point and verify
        // against the per-arity group commitment.
        let pg = &prepared_groups[0];
        let point: Vec<Ef> = (0..pg.descriptor.arity).map(|b| ef_u64(3 + b as u64)).collect();
        let col = 0usize;
        let value = ef_eval(&pg.columns[col], &point);
        let opening = prove_batch_open_committed_ef(
            &pg.whir, &pg.descriptor.commitment, &pg.protocol, pg.descriptor.columns,
            pg.prover_data.clone().expect("group prover data"), &[col], vec![pg.columns[col].clone()],
            &[point.clone()], &[value]).expect("pooled group opening");
        assert!(verify_batch_open_committed_ef(
            &pg.whir, &pg.descriptor.commitment, &pg.protocol, pg.descriptor.columns,
            &[col], &[point], &[value], &opening));

        // Synthetic 6-op graph: per-op wire still exceeds MAX_EFFECTIVE_OPENINGS.
        let execution = TrustedExecution {
            inputs: [(x, store.get(x).to_vec())].into(),
            outputs: [(outs[5], store.get(outs[5]).to_vec())].into(),
        };
        let whir = Whir::new_testing(5);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &cached, 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("synthetic proof");
        let budget = proof_budget(&proof, &proof.aux, &ops, &model).expect("budget");
        assert!(budget.openings <= MAX_EFFECTIVE_OPENINGS,
            "pooled wire must fit the 64-opening cap (K={})", budget.openings);
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution),
            "pooled synthetic proof must verify");
        // Wire version and layout tampering are rejected.
        let mut bad: BoundExecutionProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.aux_layout += 1;
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &bad,
            &PublicStatement::Generic, &model, &execution));
        let mut bad: BoundExecutionProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.aux_groups[0].columns += 1;
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &bad,
            &PublicStatement::Generic, &model, &execution));
        eprintln!("O7-M2 synthetic: pooled_K={} aux_groups={} group_cols={}",
            budget.openings, plan.groups.len(),
            plan.groups.iter().map(|g| g.1).sum::<usize>());
        let _ = std::fs::remove_dir_all(&cache);
    }

    /// CI lint: no production `verify_same_poly(...).is_none()` discard
    /// without a `LINT-ALLOW` justification. Mirrors
    /// scripts/check_same_poly_binding.py.
    #[test]
    fn same_poly_discard_lint() {
        let src = include_str!("compose.rs");
        let prod = src.split("#[cfg(test)]").next().unwrap_or(src);
        let lines: Vec<&str> = prod.lines().collect();
        let mut hits = Vec::new();
        for (i, line) in lines.iter().enumerate() {
            if !line.contains("verify_same_poly") { continue; }
            let end = (i + 12).min(lines.len());
            if !lines[i..end].iter().any(|x| x.contains(".is_none()")) { continue; }
            let start = i.saturating_sub(2);
            if lines[start..end].iter().any(|x| x.contains("LINT-ALLOW")) { continue; }
            hits.push(i + 1);
        }
        assert!(hits.is_empty(),
            "unauthenticated verify_same_poly(...).is_none() at lines {:?}; consume the merged claim or add LINT-ALLOW with justification",
            hits);
    }

    /// AUDIT (multi-consumer DAG): an intermediate tensor consumed by two
    /// ops must not allow one consumer's claim to be forged. The honest prover
    /// refuses the forged seed (it recomputes the store relations), and the
    /// verifier rejects the forged seed against the honest proof.
    #[test]
    fn audit_multi_consumer_forged_claim_must_reject() {
        let mut store = Store::new();
        let l = 32usize;
        let a = store.push((0..l).map(|i| from_i64((i as i64 % 7) + 1)).collect());
        let b = store.push((0..l).map(|i| from_i64((i as i64 % 5) + 2)).collect());
        let c1 = store.push((0..l).map(|i| from_i64((i as i64 % 3) + 4)).collect());
        let c2 = store.push((0..l).map(|i| from_i64((i as i64 % 4) + 6)).collect());
        let t = store.push(vec![Goldilocks::ZERO; l]);
        let y1 = store.push(vec![Goldilocks::ZERO; l]);
        let y2 = store.push(vec![Goldilocks::ZERO; l]);
        let ops = vec![
            Op::Add { a, b, c: t },
            Op::Add { a: t, b: c1, c: y1 },
            Op::Add { a: t, b: c2, c: y2 },
        ];
        forward_ops(&mut store, &ops);
        let lgl = l.trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(2 + b as u64)).collect();
        let seeds = vec![
            EfClaim { tensor_id: y1, point: point.clone(),
                value: ef_eval(store.get(y1), &point) },
            EfClaim { tensor_id: y2, point: point.clone(),
                value: ef_eval(store.get(y2), &point) },
        ];
        let proof = prove_reverse_dag(&store, &ops, &seeds,
            &mut Transcript::new(b"audit-multiconsumer")).expect("honest proof");
        assert!(verify_reverse_dag(&ops, &seeds, &proof,
            &mut Transcript::new(b"audit-multiconsumer")).is_some(),
            "honest multi-consumer DAG must verify");
        let mut forged = seeds.clone();
        forged[0].value += Ef::ONE;
        assert!(prove_reverse_dag(&store, &ops, &forged,
            &mut Transcript::new(b"audit-multiconsumer")).is_none(),
            "prover must fail closed on a forged consumer claim");
        assert!(verify_reverse_dag(&ops, &forged, &proof,
            &mut Transcript::new(b"audit-multiconsumer")).is_none(),
            "verifier must reject a forged consumer claim");
    }

    /// PR#45 B1: the RmsNorm row gadget must be pointwise zero for every
    /// rsqrt_index branch (fine / coarse / coarse2), and reject a wrong
    /// committed index. No commitments are involved.
    #[test]
    fn b1_rms_norm_row_gadget_branches() {
        let n_real = 1usize;
        let lay = rms_row_layout(n_real).unwrap();
        let gamma = ef_u64(7);
        let terms = rms_row_terms(gamma, n_real, &lay);
        let ms_values = [
            0i64,
            1i64 << 18,
            (RMS_FINE - 1) << 18,
            RMS_FINE << 18,
            (RMS_COARSE_END - 1) << 18,
            RMS_COARSE_END << 18,
            1i64 << 50,
        ];
        for &ms in &ms_values {
            let mut cols = vec![vec![Goldilocks::ZERO; 32]; lay.columns];
            let sidx = rsqrt_index(ms);
            rms_row_witness(ms, ms, 0, Goldilocks::ZERO, sidx, n_real, &lay, &mut cols, 0)
                .expect("branch witness");
            for r in 1..32 {
                rms_row_witness(0, 0, 0, Goldilocks::ZERO, 0, n_real, &lay, &mut cols, r)
                    .expect("padding witness");
            }
            for r in 0..32 {
                let mut vals = vec![Ef::ZERO; lay.columns + 1];
                vals[0] = Ef::ONE;
                for c in 0..lay.columns { vals[1 + c] = Ef::from(cols[c][r]); }
                assert_eq!(efo::virtual_eval(&terms, &vals), Ef::ZERO,
                    "row relation must vanish at ms={ms} row={r}");
            }
            // A wrong index has no witness.
            let mut bad = vec![vec![Goldilocks::ZERO; 32]; lay.columns];
            assert!(rms_row_witness(ms, ms, 0, Goldilocks::ZERO, sidx.wrapping_add(1),
                n_real, &lay, &mut bad, 0).is_none());
        }
    }

    /// Multilinear interpolant through arbitrary claim points (test helper).
    fn fake_mle_with_values(points: &[Vec<Ef>], values: &[Ef]) -> Vec<Ef> {
        let t = points[0].len();
        let n = points.len();
        let cols = 1usize << t;
        let mut aug: Vec<Vec<Ef>> = points.iter().zip(values).map(|(p, y)| {
            let mut row = Vec::with_capacity(cols + 1);
            for k in 0..cols {
                let mut v = Ef::ONE;
                for j in 0..t { if (k >> j) & 1 == 1 { v = v * p[j]; } }
                row.push(v);
            }
            row.push(*y);
            row
        }).collect();
        let mut pivots = Vec::new();
        let mut row = 0;
        for col in 0..cols {
            if row == n { break; }
            if let Some(pr) = (row..n).find(|&r| aug[r][col] != Ef::ZERO) {
                aug.swap(row, pr);
                let inv = aug[row][col].inverse();
                for c in col..=cols { aug[row][c] = aug[row][c] * inv; }
                for r in 0..n {
                    if r != row && aug[r][col] != Ef::ZERO {
                        let f = aug[r][col];
                        for c in col..=cols { aug[r][c] = aug[r][c] - f * aug[row][c]; }
                    }
                }
                pivots.push(col);
                row += 1;
            }
        }
        // The claim points may satisfy the multilinear consistency relations
        // (e.g. three collinear points); the system is still solvable when
        // the target values respect them. Rows past the rank must be trivial.
        for r in row..n {
            assert_eq!(aug[r][cols], Ef::ZERO,
                "claim values violate a multilinear consistency relation");
        }
        let mut f = vec![Ef::ZERO; cols];
        for (r, &c) in pivots.iter().enumerate() { f[c] = aug[r][cols]; }
        f
    }

    /// AUDIT RED→GREEN (RoPE): forged caller out claim with an interpolating
    /// same_poly fake; the committed full-domain out column at the six claim
    /// points rejects it.
    #[test]
    fn audit_rope_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, heads, d, shift) = (4usize, 2usize, 8usize, 16u32);
        let half = d / 2;
        let len = m * heads * d;
        let n = m * heads * half;
        let lg_n = n.trailing_zeros() as usize;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 23) - 11)).collect();
        let cosv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(20000 + ((i as i64 * 3) % 7))).collect();
        let sinv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(-3000 + ((i as i64 * 5) % 11))).collect();
        let x = store.push(xv);
        let cos = store.push(cosv);
        let sin = store.push(sinv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let range_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let ops = vec![Op::RoPE { x, cos, sin, out, range_table: range_t, m, d, shift }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let mut auxv = prepare_rope_aux(&store, &ops, &model).expect("aux");
        let mut auxp = RopeAux {
            rem_f: take(&mut auxv, AuxRole::RopeRemF),
            rem_s: take(&mut auxv, AuxRole::RopeRemS),
            mult_f: take(&mut auxv, AuxRole::RopeRemFMultiplicity),
            mult_s: take(&mut auxv, AuxRole::RopeRemSMultiplicity),
        };
        let _ = &mut auxp;
        let out_aux = prepare_rope_out_aux(&store, &ops).expect("out aux").remove(0);
        let out_commit = out_aux.descriptor.commitment.clone();
        let point: Vec<Ef> = (0..lg_n + 1).map(|b| ef_u64(17 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let mut tp = Transcript::new(b"audit-rope");
        let (proof, _claims) = prove_reverse_rope(
            &store, &ops[0], &point, genuine, auxp, out_aux, &model, &mut tp, None)
            .expect("honest proof");
        // Replay to the bind state.
        let mut tp = Transcript::new(b"audit-rope");
        tp.absorb(&bincode::serialize(&out_commit).unwrap());
        tp.absorb(b"zkie-rope-v1");
        tp.absorb_u64(m as u64); tp.absorb_u64(heads as u64);
        tp.absorb_u64(d as u64); tp.absorb_u64(shift as u64);
        tp.absorb_u64(65536);
        let _qf: Vec<Ef> = tp.ef_field_vec(lg_n);
        let g_f = tp.ef_field();
        let ft = rope_first_terms(g_f, shift);
        let (okf, z_f, _fcf) = efo::verify_virtual(&proof.first, &ft, Ef::ZERO, lg_n, &mut tp);
        assert!(okf);
        let _qs: Vec<Ef> = tp.ef_field_vec(lg_n);
        let g_s = tp.ef_field();
        let st = rope_second_terms(g_s, shift);
        let (oks, z_s, _fcs) = efo::verify_virtual(&proof.second, &st, Ef::ZERO, lg_n, &mut tp);
        assert!(oks);
        let half_log = half.trailing_zeros() as usize;
        let p_half = rope_remove_bit(&point, half_log).unwrap();
        let p0 = rope_insert_bit(&p_half, half_log, Ef::ZERO);
        let p1 = rope_insert_bit(&p_half, half_log, Ef::ONE);
        let q0 = rope_insert_bit(&z_f, half_log, Ef::ZERO);
        let q1 = rope_insert_bit(&z_s, half_log, Ef::ONE);
        // v0 = v1 = forged satisfies the verifier's selector relation.
        let ff5 = proof.first.final_evals[5];
        let fs5 = proof.second.final_evals[5];
        let claims = vec![
            (point.clone(), forged), (p0, forged), (p1, forged),
            (q0, ff5), (q1, fs5),
        ];
        let vals: Vec<Ef> = claims.iter().map(|(_, v)| *v).collect();
        let pts: Vec<Vec<Ef>> = claims.iter().map(|(p, _)| p.clone()).collect();
        let f_fake = fake_mle_with_values(&pts, &vals);
        let fake_bind = efo::prove_same_poly_ef(&f_fake, &claims, &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let mut auxd = prepare_rope_aux(&store, &ops, &model).expect("aux2");
        let d_f = auxd.remove(0).descriptor;
        let d_s = auxd.remove(0).descriptor;
        let d_mf = auxd.remove(0).descriptor;
        let d_ms = auxd.remove(0).descriptor;
        let refs = RopeAuxRefs {
            rem_f: &d_f, rem_s: &d_s, mult_f: &d_mf, mult_s: &d_ms,
        };
        let outd = prepare_rope_out_aux(&store, &ops).unwrap().remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-rope");
        let got = verify_reverse_rope(&ops[0], &point, forged, refs, &outd, &model,
            &forged_proof, &mut tv, None);
        assert!(got.is_none(), "AUDIT FAILURE: forged RoPE output claim was ACCEPTED");
    }

    /// PR#45 B1: RmsNorm reverse roundtrip and tamper rejection (direct and
    /// bound bytes entry). n_real < d exercises the public prefix selector;
    /// a small non-identity rsqrt table exercises the committed-root path and
    /// keeps rstd non-zero (so the out identity binds x and w).
    #[test]
    fn b1_rms_norm_reverse_roundtrip_and_tamper() {
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 13) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let x = store.push(xv.clone());
        let w = store.push(wv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let limb_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let ops = vec![Op::RmsNorm { x, w, out, rsqrt_table: rsqrt_t,
            limb_table: limb_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cache_dir = std::env::temp_dir()
            .join(format!("zkie-rmsnorm-{}", std::process::id()));
        let cached = commit_model_weights(&store, &ops, cache_dir.to_str().unwrap());
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let mut auxv = prepare_rms_norm_aux(&store, &ops, &model).expect("rms aux");
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let descs = [
            take(&mut auxv, AuxRole::RmsNormRowWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormRsqrtMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbLoPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbLoMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbHiPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbHiMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbLoPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbLoMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbHiPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbHiMultiplicity).descriptor.clone(),
        ];
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|b| ef_u64(2 + b as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let mut auxall = prepare_rms_norm_aux(&store, &ops, &model).expect("rms aux3");
        let auxp = RmsAux {
            row: take(&mut auxall, AuxRole::RmsNormRowWitness),
            out: take(&mut auxall, AuxRole::RmsNormOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::RmsNormRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::RmsNormRsqrtMultiplicity),
            limb_lo_pairs: take(&mut auxall, AuxRole::RmsNormLimbLoPairs),
            limb_lo_mult: take(&mut auxall, AuxRole::RmsNormLimbLoMultiplicity),
            limb_hi_pairs: take(&mut auxall, AuxRole::RmsNormLimbHiPairs),
            limb_hi_mult: take(&mut auxall, AuxRole::RmsNormLimbHiMultiplicity),
            out_limb_lo_pairs: take(&mut auxall, AuxRole::RmsNormOutLimbLoPairs),
            out_limb_lo_mult: take(&mut auxall, AuxRole::RmsNormOutLimbLoMultiplicity),
            out_limb_hi_pairs: take(&mut auxall, AuxRole::RmsNormOutLimbHiPairs),
            out_limb_hi_mult: take(&mut auxall, AuxRole::RmsNormOutLimbHiMultiplicity),
        };
        let mut tp = Transcript::new(b"b1-rmsnorm");
        let (proof, claims) = prove_reverse_rms_norm(
            &store, &ops[0], &point, value, auxp, &model, &mut tp, None).expect("rms proof");
        assert_eq!(claims.len(), 3);
        let refs = RmsAuxRefs {
            row: &descs[0], out: &descs[1], rsqrt_pairs: &descs[2],
            rsqrt_mult: &descs[3], limb_lo_pairs: &descs[4],
            limb_lo_mult: &descs[5], limb_hi_pairs: &descs[6],
            limb_hi_mult: &descs[7],
            out_limb_lo_pairs: &descs[8], out_limb_lo_mult: &descs[9],
            out_limb_hi_pairs: &descs[10], out_limb_hi_mult: &descs[11],
        };
        let mut tv = Transcript::new(b"b1-rmsnorm");
        assert!(verify_reverse_rms_norm(&ops[0], &point, value, refs, &model,
            &proof, &mut tv, None).is_some(), "honest RmsNorm must verify");

        // Tampered output claim, formula/mean-square values and lookups.
        let mut tv = Transcript::new(b"b1-rmsnorm");
        assert!(verify_reverse_rms_norm(&ops[0], &point, value + Ef::ONE, refs, &model,
            &proof, &mut tv, None).is_none());
        for idx in [1usize, 2, 3, 7] {
            let mut bad: ReverseRmsNormProof =
                bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
            bad.out.final_evals[idx] += Ef::ONE;
            let refs = RmsAuxRefs { row: &descs[0], out: &descs[1], rsqrt_pairs: &descs[2],
                rsqrt_mult: &descs[3], limb_lo_pairs: &descs[4], limb_lo_mult: &descs[5],
                limb_hi_pairs: &descs[6], limb_hi_mult: &descs[7],
                out_limb_lo_pairs: &descs[8], out_limb_lo_mult: &descs[9],
                out_limb_hi_pairs: &descs[10], out_limb_hi_mult: &descs[11] };
            let mut tv = Transcript::new(b"b1-rmsnorm");
            assert!(verify_reverse_rms_norm(&ops[0], &point, value, refs, &model,
                &bad, &mut tv, None).is_none(), "tampered out eval {idx}");
        }
        let mut bad: ReverseRmsNormProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.ms.final_evals[2] += Ef::ONE;
        let refs = RmsAuxRefs { row: &descs[0], out: &descs[1], rsqrt_pairs: &descs[2],
            rsqrt_mult: &descs[3], limb_lo_pairs: &descs[4], limb_lo_mult: &descs[5],
            limb_hi_pairs: &descs[6], limb_hi_mult: &descs[7],
            out_limb_lo_pairs: &descs[8], out_limb_lo_mult: &descs[9],
            out_limb_hi_pairs: &descs[10], out_limb_hi_mult: &descs[11] };
        let mut tv = Transcript::new(b"b1-rmsnorm");
        assert!(verify_reverse_rms_norm(&ops[0], &point, value, refs, &model,
            &bad, &mut tv, None).is_none(), "tampered x eval at the ms endpoint");
        let mut bad: ReverseRmsNormProof =
            bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
        bad.rsqrt.table_value += Ef::ONE;
        let refs = RmsAuxRefs { row: &descs[0], out: &descs[1], rsqrt_pairs: &descs[2],
            rsqrt_mult: &descs[3], limb_lo_pairs: &descs[4], limb_lo_mult: &descs[5],
            limb_hi_pairs: &descs[6], limb_hi_mult: &descs[7],
            out_limb_lo_pairs: &descs[8], out_limb_lo_mult: &descs[9],
            out_limb_hi_pairs: &descs[10], out_limb_hi_mult: &descs[11] };
        let mut tv = Transcript::new(b"b1-rmsnorm");
        assert!(verify_reverse_rms_norm(&ops[0], &point, value, refs, &model,
            &bad, &mut tv, None).is_none(), "tampered rsqrt table value");

        // Bound bytes entry.
        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof2 = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &cached, 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("RmsNorm bound proof");
        assert!(proof2.aux.iter().any(|a| a.role == AuxRole::RmsNormRowWitness));
        let bytes = bincode::serialize(&proof2).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        for bad in 0..3usize {
            let mut e = execution.clone();
            match bad {
                0 => e.inputs.get_mut(&x).unwrap()[0] += Goldilocks::ONE,
                1 => e.outputs.get_mut(&out).unwrap()[1] += Goldilocks::ONE,
                _ => e.outputs.get_mut(&out).unwrap()[3] += Goldilocks::ONE,
            }
            assert!(!verify_committed_shard_dag_bound_bytes(
                &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &e),
                "tampered RmsNorm execution {bad} must be rejected");
        }
    }

    /// PR#45 B1: RoPE reverse roundtrip and tamper rejection (direct and
    /// bound bytes entry). Two half-domain rounding identities plus the
    /// half-selector interleaving of the full out claim.
    #[test]
    fn b1_rope_reverse_roundtrip_and_tamper() {
        let mut store = Store::new();
        let (m, heads, d, shift) = (4usize, 2usize, 8usize, 16u32);
        let half = d / 2;
        let len = m * heads * d;
        let n = m * heads * half;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 23) - 11)).collect();
        let cosv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(20000 + ((i as i64 * 3) % 7))).collect();
        let sinv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(-3000 + ((i as i64 * 5) % 11))).collect();
        let x = store.push(xv.clone());
        let cos = store.push(cosv.clone());
        let sin = store.push(sinv.clone());
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let range_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let ops = vec![Op::RoPE { x, cos, sin, out, range_table: range_t,
            m, d, shift }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let mut auxv = prepare_rope_aux(&store, &ops, &model).expect("rope aux");
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let descs = [
            take(&mut auxv, AuxRole::RopeRemF).descriptor.clone(),
            take(&mut auxv, AuxRole::RopeRemS).descriptor.clone(),
            take(&mut auxv, AuxRole::RopeRemFMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RopeRemSMultiplicity).descriptor.clone(),
        ];
        let point: Vec<Ef> = (0..n.trailing_zeros() + 1)
            .map(|b| ef_u64(2 + b as u64)).collect();
        let value = ef_eval(store.get(out), &point);
        let mut auxall = prepare_rope_aux(&store, &ops, &model).expect("rope aux2");
        let auxp = RopeAux {
            rem_f: take(&mut auxall, AuxRole::RopeRemF),
            rem_s: take(&mut auxall, AuxRole::RopeRemS),
            mult_f: take(&mut auxall, AuxRole::RopeRemFMultiplicity),
            mult_s: take(&mut auxall, AuxRole::RopeRemSMultiplicity),
        };
        let out_aux = prepare_rope_out_aux(&store, &ops).unwrap().remove(0);
        let out_desc = out_aux.descriptor.clone();
        let mut tp = Transcript::new(b"b1-rope");
        let (proof, claims) = prove_reverse_rope(
            &store, &ops[0], &point, value, auxp, out_aux, &model, &mut tp, None).expect("rope proof");
        assert_eq!(claims.len(), 8);
        let refs = RopeAuxRefs { rem_f: &descs[0], rem_s: &descs[1],
            mult_f: &descs[2], mult_s: &descs[3] };
        let mut tv = Transcript::new(b"b1-rope");
        assert!(verify_reverse_rope(&ops[0], &point, value, refs, &out_desc, &model,
            &proof, &mut tv, None).is_some(), "honest RoPE must verify");

        let mut tv = Transcript::new(b"b1-rope");
        assert!(verify_reverse_rope(&ops[0], &point, value + Ef::ONE, refs, &out_desc, &model,
            &proof, &mut tv, None).is_none());
        for which in 0..3usize {
            let mut bad: ReverseRopeProof =
                bincode::deserialize(&bincode::serialize(&proof).unwrap()).unwrap();
            match which {
                0 => bad.first.final_evals[5] += Ef::ONE,
                1 => bad.second.final_evals[6] += Ef::ONE,
                _ => bad.rem_f.table_value += Ef::ONE,
            }
            let refs = RopeAuxRefs { rem_f: &descs[0], rem_s: &descs[1],
                mult_f: &descs[2], mult_s: &descs[3] };
            let mut tv = Transcript::new(b"b1-rope");
            assert!(verify_reverse_rope(&ops[0], &point, value, refs, &out_desc, &model,
                &bad, &mut tv, None).is_none(), "tampered RoPE field {which}");
        }
        let mut wrong = descs[0].clone();
        wrong.columns += 1;
        let refs = RopeAuxRefs { rem_f: &wrong, rem_s: &descs[1],
            mult_f: &descs[2], mult_s: &descs[3] };
        let mut tv = Transcript::new(b"b1-rope");
        assert!(verify_reverse_rope(&ops[0], &point, value, refs, &out_desc, &model,
            &proof, &mut tv, None).is_none());

        // Bound bytes entry: x/cos/sin are execution inputs, out the output.
        let execution = TrustedExecution {
            inputs: [(x, xv), (cos, cosv), (sin, sinv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof2 = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("RoPE bound proof");
        assert!(proof2.aux.iter().any(|a| a.role == AuxRole::RopeRemF));
        let bytes = bincode::serialize(&proof2).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(
            &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        for bad in 0..3usize {
            let mut e = execution.clone();
            match bad {
                0 => e.inputs.get_mut(&x).unwrap()[0] += Goldilocks::ONE,
                1 => e.inputs.get_mut(&cos).unwrap()[1] += Goldilocks::ONE,
                _ => e.outputs.get_mut(&out).unwrap()[2] += Goldilocks::ONE,
            }
            assert!(!verify_committed_shard_dag_bound_bytes(
                &bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &e),
                "tampered RoPE execution {bad} must be rejected");
        }
    }

    /// P1 Phase 2: RoPE cos/sin move from public execution inputs to the
    /// A registry. The reduction evaluates them against the digest-verified
    /// caller values, emits no cos/sin execution claims, and public execution
    /// extraction lists only `x` as an input.
    #[test]
    fn p1_a_table_rope_no_execution_inputs() {
        use crate::tables::{hash_a_table, LoadedATables};
        let mut store = Store::new();
        let (m, heads, d, shift) = (4usize, 2usize, 8usize, 16u32);
        let half = d / 2;
        let len = m * heads * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 7) % 23) - 11)).collect();
        let cosv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(20000 + ((i as i64 * 3) % 7))).collect();
        let sinv: Vec<Goldilocks> = (0..m * half)
            .map(|i| from_i64(-3000 + ((i as i64 * 5) % 11))).collect();
        let x = store.push(xv.clone());
        let cos = store.push(cosv.clone());
        let sin = store.push(sinv.clone());
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let range_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let ops = vec![Op::RoPE { x, cos, sin, out, range_table: range_t,
            m, d, shift }];
        forward_ops(&mut store, &ops);
        let mut model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let mut entries = std::collections::BTreeMap::new();
        let mut values = std::collections::BTreeMap::new();
        let mut digests = std::collections::BTreeMap::new();
        for (id, logical) in [(cos, &cosv), (sin, &sinv)] {
            let arity = logical.len().checked_next_power_of_two().unwrap().max(32)
                .trailing_zeros() as usize;
            let digest = hash_a_table(id, logical.len(), arity, logical);
            entries.insert(id, ATableEntry { kind: ATableKind::File,
                length: logical.len(), arity, file_path: Some("t.bin".to_string()),
                digest: Some(digest) });
            let mut padded = logical.clone();
            padded.resize(1usize << arity, Goldilocks::ZERO);
            values.insert(id, std::sync::Arc::new(padded));
            digests.insert(id, digest);
        }
        LoadedATables { entries, values, digests }.install(&mut model).expect("install A");
        assert!(!model.lookup_roots.contains_key(&cos));
        assert!(!model.lookup_roots.contains_key(&sin));
        let pubexec = crate::bundle::public_execution(&store, &ops, &[], &model)
            .expect("public execution");
        assert_eq!(pubexec.inputs.keys().copied().collect::<Vec<_>>(), vec![x]);
        assert!(pubexec.outputs.contains_key(&out));
        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(out, store.get(out).to_vec())].into(),
        };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("A RoPE bound proof");
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution));
        let mut bad = model.clone();
        std::sync::Arc::make_mut(bad.a_table_values.get_mut(&cos).unwrap())[0] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &bad, &execution),
            "changed cos values must be rejected");
        let mut bad_digest = model.clone();
        bad_digest.a_table_digests.insert(cos, [9u32; 8]);
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &bad_digest, &execution),
            "changed cos digest must be rejected");
    }

    /// PR#45 B2: public bundle + independent verifier contract, plus the
    /// tamper matrix (model root, prompt, response, output, embedding token,
    /// argmax/tie). The verifier side reads only bundle.bin + proof.bin.
    #[test]
    fn b2_public_bundle_independent_verifier_and_tamper_matrix() {
        use crate::bundle::{write_bundle, verify_bundle_dir, PublicBundle};
        let base = 8usize;
        let tokens: Vec<u32> = (0..8).collect();
        let (mut store, ops, whir, cached, _, _) = s6_lm_setup(0x71, &tokens, base, false);
        let (emb_idx, sel, thr, gate, d1, d2, out) = match (&ops[0], &ops[2]) {
            (Op::Lookup { idx, .. }, Op::Argmax { sel, thr, gate, d1, d2, out, .. }) =>
                (*idx, *sel, *thr, *gate, *d1, *d2, *out),
            _ => unreachable!(),
        };
        forward_ops(&mut store, &ops);
        let shapes: std::collections::BTreeMap<T, usize> =
            [(emb_idx, base * base), (out, base)].into();
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops).with_index_shapes(&shapes);
        let emb_idx_key = TensorKey::Index(emb_idx).encoded().unwrap();
        let emb_idx_vals: Vec<Goldilocks> = store.idx[emb_idx].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let out_key = TensorKey::Index(out).encoded().unwrap();
        let out_vals: Vec<Goldilocks> = store.idx[out].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let execution = TrustedExecution {
            inputs: [(emb_idx_key, emb_idx_vals.clone())].into(),
            outputs: [
                (sel, store.get(sel).to_vec()), (thr, store.get(thr).to_vec()),
                (gate, store.get(gate).to_vec()), (d1, store.get(d1).to_vec()),
                (d2, store.get(d2).to_vec()), (out_key, out_vals.clone()),
            ].into(),
        };
        let stmt = PublicStatement::LanguageModel {
            prompt: tokens[..3].to_vec(), response: tokens[3..].to_vec(),
            next_token: Some(0),
        };
        let proof = prove_committed_shard_dag_bound(
            &mut store, &ops, 1, &whir, &cached, 0, 0, &stmt, &model, &execution)
            .expect("LM bundle proof");
        let bytes = bincode::serialize(&proof).unwrap();
        let dir = std::env::temp_dir().join(format!("zkie-b2-bundle-{}", std::process::id()));
        let bundle = PublicBundle::new(ops.clone(), 1, stmt.clone(), model.clone(),
            execution.clone());
        write_bundle(&dir, &bundle, &bytes).unwrap();
        assert!(verify_bundle_dir(&dir), "independent verifier must accept");
        let rejects = |b: &PublicBundle, p: &[u8]| -> bool {
            write_bundle(&dir, b, p).is_ok() && !verify_bundle_dir(&dir)
        };

        // Model-root tamper: a manifest committed from a different weight.
        let wte = match &ops[0] { Op::Lookup { table, .. } => *table, _ => unreachable!() };
        if let TensorData::Owned(v) = &mut store.v[wte] { v[0] += Goldilocks::ONE; }
        let bad_cache = std::env::temp_dir()
            .join(format!("zkie-b2-badcache-{}", std::process::id()));
        let cached_bad = commit_model_weights(&store, &ops, bad_cache.to_str().unwrap());
        let model_bad = TrustedModelManifest::from_offline_commitment(
            &cached_bad, &store.owned_slices(), &ops).with_index_shapes(&shapes);
        let mut bad = bundle.clone();
        bad.model = model_bad;
        assert!(rejects(&bad, &bytes), "tampered model root must be rejected");

        // Prompt / response tamper.
        let mut bad = bundle.clone();
        bad.statement = PublicStatement::LanguageModel {
            prompt: vec![0, 1, 5], response: tokens[3..].to_vec(), next_token: Some(0) };
        assert!(rejects(&bad, &bytes), "tampered prompt must be rejected");
        let mut bad = bundle.clone();
        bad.statement = PublicStatement::LanguageModel {
            prompt: tokens[..3].to_vec(), response: vec![3, 5, 5, 6, 7],
            next_token: Some(0) };
        assert!(rejects(&bad, &bytes), "tampered response must be rejected");

        // Public output and embedding-token tamper.
        let mut bad = bundle.clone();
        bad.execution.outputs.get_mut(&out_key).unwrap()[2] += Goldilocks::ONE;
        assert!(rejects(&bad, &bytes), "tampered argmax output must be rejected");
        let mut bad = bundle.clone();
        bad.execution.inputs.get_mut(&emb_idx_key).unwrap()[base] += Goldilocks::ONE;
        assert!(rejects(&bad, &bytes), "tampered embedding token must be rejected");

        // Argmax/tie: the tied setup's first maximum is 3; claiming the tied
        // second maximum (4) in the statement or in the public argmax column
        // must both reject.
        let (mut store_t, ops_t, whir_t, cached_t, _, _) =
            s6_lm_setup(0x72, &tokens, base, true);
        let (emb_idx_t, sel_t, thr_t, gate_t, d1_t, d2_t, out_t) =
            match (&ops_t[0], &ops_t[2]) {
                (Op::Lookup { idx, .. }, Op::Argmax { sel, thr, gate, d1, d2, out, .. }) =>
                    (*idx, *sel, *thr, *gate, *d1, *d2, *out),
                _ => unreachable!(),
            };
        forward_ops(&mut store_t, &ops_t);
        let shapes_t: std::collections::BTreeMap<T, usize> =
            [(emb_idx_t, base * base), (out_t, base)].into();
        let model_t = TrustedModelManifest::from_offline_commitment(
            &cached_t, &store_t.owned_slices(), &ops_t).with_index_shapes(&shapes_t);
        let emb_key_t = TensorKey::Index(emb_idx_t).encoded().unwrap();
        let emb_vals_t: Vec<Goldilocks> = store_t.idx[emb_idx_t].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let out_key_t = TensorKey::Index(out_t).encoded().unwrap();
        let out_vals_t: Vec<Goldilocks> = store_t.idx[out_t].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let execution_t = TrustedExecution {
            inputs: [(emb_key_t, emb_vals_t)].into(),
            outputs: [
                (sel_t, store_t.get(sel_t).to_vec()), (thr_t, store_t.get(thr_t).to_vec()),
                (gate_t, store_t.get(gate_t).to_vec()), (d1_t, store_t.get(d1_t).to_vec()),
                (d2_t, store_t.get(d2_t).to_vec()), (out_key_t, out_vals_t),
            ].into(),
        };
        let stmt_t = PublicStatement::LanguageModel {
            prompt: tokens[..3].to_vec(), response: tokens[3..].to_vec(),
            next_token: Some(0),
        };
        let proof_t = prove_committed_shard_dag_bound(
            &mut store_t, &ops_t, 1, &whir_t, &cached_t, 0, 0, &stmt_t, &model_t, &execution_t)
            .expect("tied LM proof");
        let bytes_t = bincode::serialize(&proof_t).unwrap();
        let bundle_t = PublicBundle::new(ops_t.clone(), 1, stmt_t.clone(), model_t.clone(),
            execution_t.clone());
        write_bundle(&dir, &bundle_t, &bytes_t).unwrap();
        assert!(verify_bundle_dir(&dir));
        let mut bad = bundle_t.clone();
        bad.statement = PublicStatement::LanguageModel {
            prompt: tokens[..3].to_vec(), response: vec![4, 4, 5, 6, 7],
            next_token: Some(0) };
        assert!(rejects(&bad, &bytes_t), "tied second maximum claim must reject");
        let mut bad = bundle_t.clone();
        bad.execution.outputs.get_mut(&out_key_t).unwrap()[2] = Goldilocks::from_u64(4);
        assert!(rejects(&bad, &bytes_t), "forged tied argmax output must reject");
    }

    /// AUDIT RED TEST (RmsNorm F1): forge the caller's out claim while
    /// keeping the honest virtual proofs and replacing only the bind with a
    /// same_poly over an interpolating fake polynomial. Expected after the
    /// fix: rejection. Before the fix this test FAILS (attack accepted).
    #[test]
    fn audit_rms_norm_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, d, n_real) = (4usize, 8usize, 5usize);
        let len = m * d;
        let xv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 13) % 17) - 8)).collect();
        let wv: Vec<Goldilocks> = (0..len)
            .map(|i| from_i64(((i as i64 * 5) % 9) + 1)).collect();
        let x = store.push(xv);
        let w = store.push(wv);
        let out = store.push(vec![Goldilocks::ZERO; len]);
        let rsqrt_t = store.push((0..32).map(|i| from_i64(1000 + i as i64)).collect());
        let limb_t = store.push((0..65536).map(|i| from_i64(i as i64)).collect());
        let ops = vec![Op::RmsNorm { x, w, out, rsqrt_table: rsqrt_t,
            limb_table: limb_t, m, d, n_real }];
        forward_ops(&mut store, &ops);
        let cache_dir = std::env::temp_dir()
            .join(format!("zkie-audit-rms-{}", std::process::id()));
        let cached = commit_model_weights(&store, &ops, cache_dir.to_str().unwrap());
        let model = TrustedModelManifest::from_offline_commitment(
            &cached, &store.owned_slices(), &ops);
        let mut auxv = prepare_rms_norm_aux(&store, &ops, &model).expect("aux");
        let take = |v: &mut Vec<PreparedAux>, role: AuxRole| {
            let pos = v.iter().position(|p| p.descriptor.role == role).unwrap();
            v.remove(pos)
        };
        let descs = [
            take(&mut auxv, AuxRole::RmsNormRowWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutWitness).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormRsqrtPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormRsqrtMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbLoPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbLoMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbHiPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormLimbHiMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbLoPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbLoMultiplicity).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbHiPairs).descriptor.clone(),
            take(&mut auxv, AuxRole::RmsNormOutLimbHiMultiplicity).descriptor.clone(),
        ];
        let point: Vec<Ef> = (0..len.trailing_zeros())
            .map(|b| ef_u64(2 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let mut auxall = prepare_rms_norm_aux(&store, &ops, &model).expect("aux2");
        let auxp = RmsAux {
            row: take(&mut auxall, AuxRole::RmsNormRowWitness),
            out: take(&mut auxall, AuxRole::RmsNormOutWitness),
            rsqrt_pairs: take(&mut auxall, AuxRole::RmsNormRsqrtPairs),
            rsqrt_mult: take(&mut auxall, AuxRole::RmsNormRsqrtMultiplicity),
            limb_lo_pairs: take(&mut auxall, AuxRole::RmsNormLimbLoPairs),
            limb_lo_mult: take(&mut auxall, AuxRole::RmsNormLimbLoMultiplicity),
            limb_hi_pairs: take(&mut auxall, AuxRole::RmsNormLimbHiPairs),
            limb_hi_mult: take(&mut auxall, AuxRole::RmsNormLimbHiMultiplicity),
            out_limb_lo_pairs: take(&mut auxall, AuxRole::RmsNormOutLimbLoPairs),
            out_limb_lo_mult: take(&mut auxall, AuxRole::RmsNormOutLimbLoMultiplicity),
            out_limb_hi_pairs: take(&mut auxall, AuxRole::RmsNormOutLimbHiPairs),
            out_limb_hi_mult: take(&mut auxall, AuxRole::RmsNormOutLimbHiMultiplicity),
        };
        let mut tp = Transcript::new(b"audit-rmsnorm");
        let (proof, _claims) = prove_reverse_rms_norm(
            &store, &ops[0], &point, genuine, auxp, &model, &mut tp, None).expect("honest proof");

        // Replay the verifier/prover transcript to the bind position.
        let (_, _, _, rsqrt_id, limb_id, mm, dd, nn) = rms_norm_dims(&ops[0]).unwrap();
        let lgl = len.trailing_zeros() as usize;
        let lg_d = d.trailing_zeros() as usize;
        let lg_m = m.trailing_zeros() as usize;
        let arity = rms_row_arity(m).unwrap();
        let lay = rms_row_layout(n_real).unwrap();
        let rsqrt_len = model.lookup_lengths[&rsqrt_id];
        let limb_len = model.lookup_lengths[&limb_id];
        let mut t = Transcript::new(b"audit-rmsnorm");
        t.absorb(&bincode::serialize(&descs[1].commitment).unwrap());
        t.absorb(b"zkie-rmsnorm-v1");
        t.absorb_u64(mm as u64); t.absorb_u64(dd as u64);
        t.absorb_u64(nn as u64); t.absorb_u64(rsqrt_len as u64);
        t.absorb_u64(limb_len as u64);
        let u_row = t.ef_field_vec(arity);
        let g_row = t.ef_field();
        let row_terms = rms_row_terms(g_row, n_real, &lay);
        let (ok, z_row, _) = efo::verify_virtual(&proof.row, &row_terms, Ef::ZERO, arity, &mut t);
        assert!(ok);
        let u_ms = t.ef_field_vec(lg_m);
        let g_ms = t.ef_field();
        let d_inv = ef_u64(d as u64).inverse();
        let ms_terms = vec![
            (g_ms, vec![0usize, 1usize, 2usize, 2usize]),
            (-g_ms * d_inv, vec![0usize, 3usize]),
        ];
        let (ok, z_ms, _) = efo::verify_virtual(&proof.ms, &ms_terms, Ef::ZERO, lgl, &mut t);
        assert!(ok);
        let q_out = t.ef_field_vec(lgl);
        let g_out = t.ef_field();
        let g_out2 = t.ef_field();
        let two32 = ef_u64(1u64 << 32);
        let half32 = ef_u64(1u64 << 31);
        let out_terms = vec![
            (g_out, vec![0usize, 1usize, 2usize, 3usize]),
            (-g_out * two32, vec![0usize, 4usize]),
            (-g_out, vec![0usize, 5usize]),
            (-g_out * ef_u64(1u64 << 16), vec![0usize, 6usize]),
            (g_out * half32, vec![0usize, 7usize]),
            (g_out2, vec![0usize, 4usize]),
            (g_out2 * half32, vec![0usize]),
            (-g_out2, vec![0usize, 8usize]),
            (-g_out2 * ef_u64(1u64 << 16), vec![0usize, 9usize]),
        ];
        let (ok, z_out, _) = efo::verify_virtual(&proof.out, &out_terms, Ef::ZERO, lgl, &mut t);
        assert!(ok);
        let _ = (u_row, u_ms, q_out, z_row, z_ms);
        let fo = proof.out.final_evals.clone();
        let fo4 = fo[4];
        // f' = out + a*chi0 + b*chi1 with f'(point)=forged, f'(z_out)=fo4.
        let out_ef = ef_lift(store.get(out));
        let dlt = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z_out).unwrap();
        let v11 = efo::eq_poly(&u1, &z_out).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = dlt * v11 * det.inverse();
        let b = -dlt * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..len).map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z_out.clone(), fo4)], &mut t).0;
        // Regenerate the post-bind auxiliary lookups under the forged
        // transcript state (a real malicious prover can do this; the
        // transcript is public input to the prover).
        let fo3 = fo[3]; let fo5 = fo[5]; let fo6 = fo[6];
        let mut auxatk = prepare_rms_norm_aux(&store, &ops, &model).expect("aux3");
        let rsqrt_pairs = take(&mut auxatk, AuxRole::RmsNormRsqrtPairs);
        let rsqrt_mult = take(&mut auxatk, AuxRole::RmsNormRsqrtMultiplicity);
        let lo_pairs = take(&mut auxatk, AuxRole::RmsNormLimbLoPairs);
        let lo_mult = take(&mut auxatk, AuxRole::RmsNormLimbLoMultiplicity);
        let hi_pairs = take(&mut auxatk, AuxRole::RmsNormLimbHiPairs);
        let hi_mult = take(&mut auxatk, AuxRole::RmsNormLimbHiMultiplicity);
        let mut p_rstd_atk = z_out[lg_d..].to_vec();
        p_rstd_atk.resize(arity, Ef::ZERO);
        let rsqrt_xs: Vec<u32> = (0..m)
            .map(|r| to_i64(rsqrt_pairs.columns[0][r]) as u32).collect();
        let rsqrt_ys: Vec<Goldilocks> = (0..m)
            .map(|r| rsqrt_pairs.columns[1][r]).collect();
        let rsqrt_atk = internal_lookup_prove(&store, rsqrt_id, rsqrt_pairs,
            rsqrt_mult, 0, 1, &rsqrt_xs, &rsqrt_ys, &p_rstd_atk, fo3,
            &model, &mut t, None).expect("rsqrt atk");
        let lo_xs: Vec<u32> = lo_pairs.columns[0].iter()
            .map(|&v| to_i64(v) as u32).collect();
        let lo_ys: Vec<Goldilocks> = lo_pairs.columns[0].clone();
        let limb_lo_atk = internal_lookup_prove(&store, limb_id, lo_pairs,
            lo_mult, 0, 0, &lo_xs, &lo_ys, &z_out, fo5, &model, &mut t, None)
            .expect("limb lo atk");
        let hi_xs: Vec<u32> = hi_pairs.columns[1].iter()
            .map(|&v| to_i64(v) as u32).collect();
        let hi_ys: Vec<Goldilocks> = hi_pairs.columns[1].clone();
        let limb_hi_atk = internal_lookup_prove(&store, limb_id, hi_pairs,
            hi_mult, 1, 1, &hi_xs, &hi_ys, &z_out, fo6, &model, &mut t, None)
            .expect("limb hi atk");
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        forged_proof.rsqrt = rsqrt_atk;
        forged_proof.limb_lo = limb_lo_atk;
        forged_proof.limb_hi = limb_hi_atk;
        let refs = RmsAuxRefs {
            row: &descs[0], out: &descs[1], rsqrt_pairs: &descs[2],
            rsqrt_mult: &descs[3], limb_lo_pairs: &descs[4],
            limb_lo_mult: &descs[5], limb_hi_pairs: &descs[6],
            limb_hi_mult: &descs[7],
            out_limb_lo_pairs: &descs[8], out_limb_lo_mult: &descs[9],
            out_limb_hi_pairs: &descs[10], out_limb_hi_mult: &descs[11],
        };
        let mut tv = Transcript::new(b"audit-rmsnorm");
        let got = verify_reverse_rms_norm(&ops[0], &point, forged, refs, &model,
            &forged_proof, &mut tv, None);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged RmsNorm output claim was ACCEPTED");
    }

    /// AUDIT RED TEST (systemic same_poly output-binding gap): a malicious
    /// prover keeps the honest virtual proof and cross-point data but forges
    /// the caller's output claim, replacing only the same_poly bind with one
    /// over an interpolating fake polynomial f'. The verifier discards the
    /// merged claim, so it cannot tell f' from the real out column.
    /// Expected after the fix: rejection. Before the fix this test FAILS.
    #[test]
    fn audit_scale_vec_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let l = 32usize;
        let xv: Vec<Goldilocks> = (0..l).map(|i| from_i64((i as i64 % 7) + 1)).collect();
        let sv: Vec<Goldilocks> = (0..8).map(|i| from_i64((i as i64 % 3) + 1)).collect();
        let x = store.push(xv);
        let scale = store.push(sv);
        let out = store.push(vec![Goldilocks::ZERO; l]);
        let ops = vec![Op::ScaleVec { x, scale, out, shift: 0 }];
        forward_ops(&mut store, &ops);
        let lgl = l.trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(3 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;

        // Honest proof for the honest claim.
        let aux_prove = prepare_scale_vec_out_aux(&store, &ops).expect("aux").remove(0);
        let commitment = aux_prove.descriptor.commitment.clone();
        let mut tp = Transcript::new(b"audit-scalevec");
        let terms = exact_product_terms();
        let (proof, _claims) = prove_reverse_scale_vec(
            &store, &ops[0], &point, genuine, aux_prove, &mut tp).expect("honest proof");

        // Replay the post-virtual transcript state (pre-bind).
        let mut tp = Transcript::new(b"audit-scalevec");
        tp.absorb(&bincode::serialize(&commitment).unwrap());
        let _q: Vec<Ef> = tp.ef_field_vec(lgl);
        let (ok, z, _fc) = efo::verify_virtual(&proof.prod, &terms, Ef::ZERO, lgl, &mut tp);
        assert!(ok);
        let fe3 = proof.prod.final_evals[3];
        // f' = out + a*eq(point) + b*eq(z), with f'(point)=forged, f'(z)=fe3.
        let out_ef = ef_lift(store.get(out));
        let d = forged - ef_eval(store.get(out), &point);
        // Multilinear basis with known values at `point` and `z`: chi_0 =
        // prod(1-X_j) and chi_1 = prod X_j.
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z).unwrap();
        let v11 = efo::eq_poly(&u1, &z).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..l)
            .map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;

        // Sanity: the fake bind itself must verify at the same transcript state.
        let mut tchk = Transcript::new(b"audit-scalevec");
        tchk.absorb(&bincode::serialize(&commitment).unwrap());
        let _q2: Vec<Ef> = tchk.ef_field_vec(lgl);
        let (ok2, z2, _fc2) = efo::verify_virtual(&forged_proof.prod, &terms, Ef::ZERO, lgl, &mut tchk);
        assert!(ok2 && z2 == z);
        let bind_ok = efo::verify_same_poly(&forged_proof.bind,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tchk).is_some();
        eprintln!("AUDIT bind_ok={bind_ok}");
        let desc = prepare_scale_vec_out_aux(&store, &ops).expect("aux2").remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-scalevec");
        let got = verify_reverse_scale_vec(&ops[0], &point, forged, &desc, &forged_proof, &mut tv);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged ScaleVec output claim was ACCEPTED");
    }

    /// AUDIT RED→GREEN (BroadcastScale): forged caller out claim with an
    /// interpolating same_poly fake must be rejected once the out witness is
    /// committed and the merged claim is opened against it.
    #[test]
    fn audit_broadcast_scale_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let l = 32usize;
        let h = 4usize;
        let xv: Vec<Goldilocks> = (0..l).map(|i| from_i64((i as i64 % 5) + 1)).collect();
        let sv: Vec<Goldilocks> = (0..l / h).map(|i| from_i64((i as i64 % 3) + 1)).collect();
        let x = store.push(xv);
        let scale = store.push(sv);
        let out = store.push(vec![Goldilocks::ZERO; l]);
        let ops = vec![Op::BroadcastScale { x, scale, out, h }];
        forward_ops(&mut store, &ops);
        let lgl = l.trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(5 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let aux_prove = prepare_broadcast_scale_out_aux(&store, &ops).expect("aux").remove(0);
        let commitment = aux_prove.descriptor.commitment.clone();
        let mut tp = Transcript::new(b"audit-broadcast-scale");
        let terms = exact_product_terms();
        let (proof, _claims) = prove_reverse_broadcast_scale(
            &store, &ops[0], &point, genuine, aux_prove, &mut tp).expect("honest proof");
        let mut tp = Transcript::new(b"audit-broadcast-scale");
        tp.absorb(&bincode::serialize(&commitment).unwrap());
        let _q: Vec<Ef> = tp.ef_field_vec(lgl);
        let (ok, z, _fc) = efo::verify_virtual(&proof.prod, &terms, Ef::ZERO, lgl, &mut tp);
        assert!(ok);
        let fe3 = proof.prod.final_evals[3];
        let out_ef = ef_lift(store.get(out));
        let d = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z).unwrap();
        let v11 = efo::eq_poly(&u1, &z).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..l).map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let mut tchk = Transcript::new(b"audit-broadcast-scale");
        tchk.absorb(&bincode::serialize(&commitment).unwrap());
        let _q2: Vec<Ef> = tchk.ef_field_vec(lgl);
        let (ok2, z2, _fc2) = efo::verify_virtual(&forged_proof.prod, &terms, Ef::ZERO, lgl, &mut tchk);
        assert!(ok2 && z2 == z);
        let bind_ok = efo::verify_same_poly(&forged_proof.bind,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tchk).is_some();
        eprintln!("AUDIT broadcast-scale bind_ok={bind_ok}");
        let desc = prepare_broadcast_scale_out_aux(&store, &ops).expect("aux2").remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-broadcast-scale");
        let got = verify_reverse_broadcast_scale(&ops[0], &point, forged, &desc,
            &forged_proof, &mut tv);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged BroadcastScale output claim was ACCEPTED");
    }

    /// AUDIT RED→GREEN (ScaleVecShifted): forged caller out claim with an
    /// interpolating same_poly fake; the committed out column at the merged
    /// point rejects it.
    #[test]
    fn audit_scale_vec_shifted_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let l = 32usize;
        let shift = 4u32;
        let xv: Vec<Goldilocks> = (0..l).map(|i| from_i64((i as i64 % 7) - 3)).collect();
        let sv: Vec<Goldilocks> = (0..4).map(|i| from_i64((i as i64) + 1)).collect();
        let x = store.push(xv);
        let scale = store.push(sv);
        let out = store.push(vec![Goldilocks::ZERO; l]);
        store.push((0..(1usize << shift))
            .map(|i| Goldilocks::from_u64(i as u64)).collect());
        let ops = vec![Op::ScaleVec { x, scale, out, shift }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let lgl = l.trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(7 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let aux_prove = prepare_scale_vec_remainder_aux(&store, &ops, &model)
            .expect("aux").remove(0);
        let commitment = aux_prove.descriptor.commitment.clone();
        let mut tp = Transcript::new(b"audit-scalevec-shift");
        let (proof, _claims) = prove_reverse_scale_vec_shifted(
            &store, &ops[0], &point, genuine, aux_prove, &mut tp).expect("honest proof");
        let mut tp = Transcript::new(b"audit-scalevec-shift");
        tp.absorb(&bincode::serialize(&commitment).unwrap());
        tp.absorb(b"zkie-scalevec-shift-v1");
        let q: Vec<Ef> = tp.ef_field_vec(lgl);
        let gamma = tp.ef_field();
        let terms = scale_vec_shift_terms(shift as usize, gamma);
        let (ok, z, _fc) = efo::verify_virtual(&proof.prod, &terms, Ef::ZERO, lgl, &mut tp);
        assert!(ok);
        let _ = q;
        let fe3 = proof.prod.final_evals[3];
        let out_ef = ef_lift(store.get(out));
        let d = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z).unwrap();
        let v11 = efo::eq_poly(&u1, &z).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..l).map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let desc = prepare_scale_vec_remainder_aux(&store, &ops, &model)
            .expect("aux2").remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-scalevec-shift");
        let got = verify_reverse_scale_vec_shifted(&ops[0], &point, forged,
            Some(&desc), &forged_proof, &mut tv);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged ScaleVecShifted output claim was ACCEPTED");
    }

    /// PR#45 B1: ScaleGate reverse roundtrip (exact and rounded), plus
    /// output/aux tamper rejection.
    #[test]
    fn b1_scale_gate_reverse_roundtrip_and_tamper() {
        for shift in [0u32, 4] {
            let mut store = Store::new();
            let (m, h, n, col) = (4usize, 8usize, 8usize, 3usize);
            let x = store.push((0..m * h).map(|i| from_i64(i as i64 - 12)).collect());
            let gate = store.push((0..m * n).map(|i| from_i64((i as i64 % 7) - 3)).collect());
            let out = store.push(vec![Goldilocks::ZERO; m * h]);
            let ops = vec![Op::ScaleGate { x, gate, col, out, m, n, h, shift }];
            forward_ops(&mut store, &ops);
            let model = TrustedModelManifest::from_offline_commitment(
                &[], &store.owned_slices(), &ops);
            let point: Vec<Ef> = (0..(m * h).trailing_zeros()).map(|b| ef_u64(3 + b as u64)).collect();
            let value = ef_eval(store.get(out), &point);
            let aux = if shift == 0 { None } else {
                Some(prepare_scale_gate_aux(&store, &ops, &model).unwrap().remove(0))
            };
            let auxd = aux.as_ref().map(|a| a.descriptor.clone());
            let out_aux = prepare_scale_gate_out_aux(&store, &ops).unwrap().remove(0);
            let out_desc = out_aux.descriptor.clone();
            let mut tp = Transcript::new(b"b1-scalegate");
            let (proof, claims) = prove_reverse_scale_gate(
                &store, &ops[0], &point, value, aux, out_aux, &mut tp, None).unwrap();
            assert_eq!(claims.len(), 2);
            assert_eq!(claims[0].tensor_id, x);
            assert_eq!(claims[1].tensor_id, gate);
            let mut tv = Transcript::new(b"b1-scalegate");
            let got = verify_reverse_scale_gate(
                &ops[0], &point, value, auxd.as_ref(), &out_desc, &proof, &mut tv, None);
            assert!(got.is_some(), "shift={shift} honest ScaleGate must verify");
            // Tampered output claim.
            let mut tv = Transcript::new(b"b1-scalegate");
            assert!(verify_reverse_scale_gate(
                &ops[0], &point, value + Ef::ONE, auxd.as_ref(), &out_desc, &proof, &mut tv, None).is_none());
            // Tampered x eval inside the product virtual.
            let mut bad = proof.clone();
            bad.prod.final_evals[1] += Ef::ONE;
            let mut tv = Transcript::new(b"b1-scalegate");
            assert!(verify_reverse_scale_gate(
                &ops[0], &point, value, auxd.as_ref(), &out_desc, &bad, &mut tv, None).is_none());
            if shift > 0 {
                let mut bad = proof.clone();
                bad.remainder_bits[0] += Ef::ONE;
                let mut tv = Transcript::new(b"b1-scalegate");
                assert!(verify_reverse_scale_gate(
                    &ops[0], &point, value, auxd.as_ref(), &out_desc, &bad, &mut tv, None).is_none());
                // Descriptor with the wrong column count is rejected.
                let mut wrong = auxd.clone().unwrap();
                wrong.columns += 1;
                let mut tv = Transcript::new(b"b1-scalegate");
                assert!(verify_reverse_scale_gate(
                    &ops[0], &point, value, Some(&wrong), &out_desc, &proof, &mut tv, None).is_none());
            }
        }
    }

    /// AUDIT RED→GREEN (ScaleGate): forged caller out claim with an
    /// interpolating same_poly fake; the committed out column at the merged
    /// point rejects it (shift>0 path; shift0 shares the same binding).
    #[test]
    fn audit_scale_gate_forged_output_claim_must_reject() {
        let mut store = Store::new();
        let (m, h, n, col, shift) = (4usize, 8usize, 8usize, 3usize, 4u32);
        let x = store.push((0..m * h).map(|i| from_i64(i as i64 - 12)).collect());
        let gate = store.push((0..m * n).map(|i| from_i64((i as i64 % 7) - 3)).collect());
        let out = store.push(vec![Goldilocks::ZERO; m * h]);
        let ops = vec![Op::ScaleGate { x, gate, col, out, m, n, h, shift }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(
            &[], &store.owned_slices(), &ops);
        let lgl = (m * h).trailing_zeros() as usize;
        let point: Vec<Ef> = (0..lgl).map(|b| ef_u64(9 + b as u64)).collect();
        let genuine = ef_eval(store.get(out), &point);
        let forged = genuine + Ef::ONE;
        let aux = prepare_scale_gate_aux(&store, &ops, &model).expect("aux").remove(0);
        let out_aux = prepare_scale_gate_out_aux(&store, &ops).expect("out aux").remove(0);
        let out_commit = out_aux.descriptor.commitment.clone();
        let mut tp = Transcript::new(b"audit-scalegate");
        let (proof, _claims) = prove_reverse_scale_gate(
            &store, &ops[0], &point, genuine, Some(aux), out_aux, &mut tp, None)
            .expect("honest proof");
        let mut tp = Transcript::new(b"audit-scalegate");
        tp.absorb(&bincode::serialize(&out_commit).unwrap());
        tp.absorb(b"zkie-scalegate-v1");
        tp.absorb_u64(shift as u64);
        let _q: Vec<Ef> = tp.ef_field_vec(lgl);
        let gamma = tp.ef_field();
        let terms = scale_vec_shift_terms(shift as usize, gamma);
        let (ok, z, _fc) = efo::verify_virtual(&proof.prod, &terms, Ef::ZERO, lgl, &mut tp);
        assert!(ok);
        let fe3 = proof.prod.final_evals[3];
        let out_ef = ef_lift(store.get(out));
        let d = forged - ef_eval(store.get(out), &point);
        let u0 = vec![Ef::ZERO; lgl];
        let u1 = vec![Ef::ONE; lgl];
        let v00 = efo::eq_poly(&u0, &point).unwrap();
        let v01 = efo::eq_poly(&u1, &point).unwrap();
        let v10 = efo::eq_poly(&u0, &z).unwrap();
        let v11 = efo::eq_poly(&u1, &z).unwrap();
        let det = v00 * v11 - v01 * v10;
        let a = d * v11 * det.inverse();
        let b = -d * v10 * det.inverse();
        let chi0 = efo::eq_evals(&u0);
        let chi1 = efo::eq_evals(&u1);
        let f_fake: Vec<Ef> = (0..m * h)
            .map(|i| out_ef[i] + a * chi0[i] + b * chi1[i]).collect();
        let fake_bind = efo::prove_same_poly_ef(&f_fake,
            &[(point.clone(), forged), (z.clone(), fe3)], &mut tp).0;
        let mut forged_proof = proof;
        forged_proof.bind = fake_bind;
        let auxd = prepare_scale_gate_aux(&store, &ops, &model)
            .expect("aux2").remove(0).descriptor;
        let outd = prepare_scale_gate_out_aux(&store, &ops)
            .expect("out aux2").remove(0).descriptor;
        let mut tv = Transcript::new(b"audit-scalegate");
        let got = verify_reverse_scale_gate(&ops[0], &point, forged,
            Some(&auxd), &outd, &forged_proof, &mut tv, None);
        assert!(got.is_none(),
            "AUDIT FAILURE: forged ScaleGate output claim was ACCEPTED");
    }

    /// S9 WAVE-1 A2: tie_zero/tie_less are charged their real per-round
    /// x-degree (4/5), not the default 3; the γ term is 4·|final_evals|.
    #[test]
    fn s9_a2_virtual_degree_charges_tie_zero_less() {
        let mk = |rounds: usize, evals: usize| EfVirtualProof {
            rounds: vec![vec![Ef::ZERO; 6]; rounds],
            final_evals: vec![Ef::ZERO; evals],
        };
        let p = mk(7, 3);
        let mut b3 = ProofBudget::default();
        b3.virtual_proof(&p, 3).unwrap();
        let mut b4 = ProofBudget::default();
        b4.virtual_proof(&p, 4).unwrap();
        let mut b5 = ProofBudget::default();
        b5.virtual_proof(&p, 5).unwrap();
        let gamma = 4 * 3;
        assert_eq!(b3.weighted, 3 * 7 + gamma);
        assert_eq!(b4.weighted, 4 * 7 + gamma); // tie_zero call-site degree
        assert_eq!(b5.weighted, 5 * 7 + gamma); // tie_less call-site degree
        assert!(b4.weighted > b3.weighted && b5.weighted > b4.weighted);
    }

    #[test]
    fn ef_eval_shared_prefix_matches_per_point() {
        let vals: Vec<Goldilocks> = (0..(1usize << 8))
            .map(|i| Goldilocks::from_u64((i as u64) * 7 + 3)).collect();
        let shared: Vec<Ef> = (0..5)
            .map(|j| Ef::from(Goldilocks::from_u64((j as u64) * 11 + 1))).collect();
        let mut points: Vec<Vec<Ef>> = Vec::new();
        for e in 0..6usize {
            let mut p = shared.clone();
            for b in 0..3 {
                p.push(if (e >> b) & 1 == 1 { Ef::ONE } else { Ef::ZERO });
            }
            points.push(p);
        }
        // Also exercise the no-shared-prefix fallback.
        let mut other = shared.clone();
        other[0] = Ef::from(Goldilocks::from_u64(999));
        other.extend_from_slice(&[Ef::ZERO, Ef::ONE, Ef::ZERO]);
        points.push(other);
        let refs: Vec<&[Ef]> = points.iter().map(Vec::as_slice).collect();
        let got = ef_eval_shared_prefix(&vals, &refs).expect("shared-prefix eval");
        for (p, g) in points.iter().zip(got) {
            assert_eq!(g, ef_eval(&vals, p));
        }
        // All points identical: the shared prefix is the whole point.
        let same = vec![points[0].clone(); 3];
        let same_refs: Vec<&[Ef]> = same.iter().map(Vec::as_slice).collect();
        let got_same = ef_eval_shared_prefix(&vals, &same_refs).expect("identical-point eval");
        for g in got_same { assert_eq!(g, ef_eval(&vals, &points[0])); }
    }

    /// S9 2d: the sub-table split math must reassemble the original MLE:
    /// f(r) = Σ_h eq(r_high, h)·f_h(r_low). Uses 16 tiny (2^5) chunks with
    /// chunk_bits = 4 standing in for 2^24 chunks of a 2^28 tensor; only the
    /// grouping/weights are exercised (no PCS proving).
    #[test]
    fn s9_weight_subtable_split_grouping_reassembles_mle() {
        let id = 1usize;
        let ops = vec![Op::MatMul { a: 0, b: id, c: 2, m: 1, k: 1, n: 512 }];
        let whir = zkie_core::pcs::whir::Whir::with_params(5, VERIFIER_SECURITY, 0);
        let mut trusted = Vec::new();
        for h in 0..16usize {
            let data = vec![Goldilocks::ZERO; 32];
            let refs: [&[Goldilocks]; 1] = [data.as_slice()];
            let (commitment, _, _, _) = whir.commit_batch(&refs);
            trusted.push(TrustedWeightBatch {
                commitment, arity: 5, num_tables: 1, num_vars: 5,
                security: VERIFIER_SECURITY, pow_bits: 0,
                table_ids: vec![id], tensor_lengths: vec![512],
                chunk_bits: 4, chunk_index: h,
            });
        }
        let mut lengths = std::collections::BTreeMap::new();
        lengths.insert(0usize, 1usize);
        lengths.insert(id, 512usize);
        lengths.insert(2usize, 512usize);
        let model = TrustedModelManifest {
            batches: trusted,
            graph: bincode::serialize(&ops).unwrap(),
            tensor_lengths: lengths,
            lookup_roots: Default::default(),
            lookup_lengths: Default::default(),
            identity_tables: Default::default(),
            a_tables: Default::default(),
            a_table_values: Default::default(),
            a_table_digests: Default::default(),
        };
        let mut rng = XorShift64::new(0x5B17);
        let f: Vec<Goldilocks> = (0..512).map(|_| rng.field()).collect();
        let r: Vec<Ef> = (0..9).map(|_| rng.ef_field()).collect();
        let value = ef_eval(&f, &r);
        let leaves = vec![EfClaim { tensor_id: id, point: r.clone(), value }];
        let grouping = group_reverse_weights(&model, &ops, &leaves).expect("16-chunk grouping");
        assert_eq!(grouping.groups.len(), 16);
        assert_eq!(grouping.checks.len(), 1);
        let mut sum = Ef::ZERO;
        for &(bi, pos, weight) in &grouping.checks[0].1 {
            assert!(grouping.groups[bi][pos].2.is_none());
            let low = &grouping.groups[bi][pos].1;
            assert_eq!(low.as_slice(), &r[..5]);
            let h = model.batches[bi].chunk_index;
            let chunk = &f[h * 32..(h + 1) * 32];
            sum = sum + weight * ef_eval(chunk, low);
        }
        assert_eq!(sum, value, "split reassembly must equal the full MLE");
        // Missing / duplicate chunks are rejected by the manifest checks.
        let mut missing = model.clone();
        missing.batches.pop();
        assert!(trusted_weight_locations(&missing, &ops).is_none());
        let mut duplicate = model.clone();
        duplicate.batches[1].chunk_index = 0;
        assert!(trusted_weight_locations(&duplicate, &ops).is_none());
    }

    /// S8 fixture: the 25-bit GeluIndex path (GeluIndexXRange aux).
    fn s8_gelu_fixture()
        -> (Vec<Op>, zkie_core::pcs::whir::Whir, TrustedModelManifest, TrustedExecution, Vec<u8>)
    {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let xv: Vec<Goldilocks> = [0i64, (1 << 23) - 1, -(1 << 23), 1 << 22, -(1 << 22), 1, -1, 2]
            .into_iter().map(from_i64).collect();
        let x = store.push(xv.clone());
        let idx = store.push_idx(vec![]);
        let ops = vec![Op::GeluIndex { x, out: idx, offset: 1 << 23, table_len: 1 << 24 }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(&[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, 8usize)].into());
        let idx_key = TensorKey::Index(idx).encoded().unwrap();
        let idx_vals: Vec<Goldilocks> = store.idx[idx].iter()
            .map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let execution = TrustedExecution {
            inputs: [(x, xv)].into(),
            outputs: [(idx_key, idx_vals)].into(),
        };
        let whir = Whir::with_params(5, VERIFIER_SECURITY, 17);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("S8 Gelu fixture proof");
        let bytes = bincode::serialize(&proof).unwrap();
        (ops, whir, model, execution, bytes)
    }

